16. type DockerContainer struct{}
17. 
18. func (d *DockerContainer) shell(t transport.Transport) transport.Shell {
19. 	if t.OS() == spec.OSWindows {
20. 		return transport.ShellPowerShell
21. 	}
22. 	return transport.ShellSh
23. }
24. 
25. func (d *DockerContainer) run(ctx context.Context, t transport.Transport, step, script string, env map[string]string, timeout int) (transport.Result, error) {
26. 	r, err := t.Exec(ctx, transport.Cmd{Shell: d.shell(t), Script: script, Env: env, TimeoutSec: timeout})
27. 	if err != nil {
28. 		return r, stepErr("ERR_CONNECT", t.Host(), step, err)
29. 	}
30. 	return r, nil
31. }
32. 
33. func (d *DockerContainer) Preflight(ctx context.Context, t transport.Transport, rc ReleaseCtx) error {
34. 	r, err := d.run(ctx, t, "PREFLIGHT", `docker version --format '{{.Server.Version}}'`, nil, 60)
35. 	if err != nil {
36. 		return err
37. 	}
38. 	if r.ExitCode != 0 {
39. 		return stepErr("ERR_PREFLIGHT", t.Host(), "PREFLIGHT",
40. 			fmt.Errorf("docker daemon unavailable: %s", truncOut(r)))
41. 	}
42. 	return nil
43. }
