46. func imageRef(a *spec.Artifact) string {
47. 	src := a.Source
48. 	if src.Digest != "" {
49. 		return src.Image + "@" + src.Digest
50. 	}
51. 	tag := src.Tag
52. 	if tag == "" {
53. 		tag = a.Version
54. 	}
