 if($LASTEXITCODE -ne 0){ exit %d }
 exit 0`, name, d.runArgs(rc), ref, ExitServiceStart)
 	} else {
 		script = fmt.Sprintf(`docker rm -f '%s' >/dev/null 2>&1 || true
 docker run %s '%s' || exit %d
 exit 0`, name, d.runArgs(rc), ref, ExitServiceStart)
 	}
