484. // deployDocker = D-steps (DESIGN §9.6) with image-id rollback. Emits the same
485. // structured step records as the file-based path for its executed steps: FETCH
486. // (image pull), START (rm -f old + run new), HEALTH, FINALIZE (manifest write),
487. // and ROLLBACK on failure — each carrying app/host/step/version/duration_ms.
488. func (e *Engine) deployDocker(ctx context.Context, sl stepLogger, t transport.Transport, s *spec.Deployment,
489. 	p layout.Paths, dc *pattern.DockerContainer, rc pattern.ReleaseCtx, m *Manifest) (*Status, error) {
490. 	host := t.Host()
491. 	sl = sl.forHost(host)
492. 	started := time.Now().UTC()
493. 	if m != nil && m.CurrentVersion == s.Artifact.Version {
494. 		if st, err := dc.Status(ctx, t, rc); err == nil && st == "running" {
495. 			return statusFrom(m, host, st), nil
496. 		}
497. 	}
498. 	prev, oldImage := "", ""
499. 	if m != nil {
500. 		prev = m.CurrentVersion
501. 		oldImage = m.Extra["image_id"]
502. 	}
503. 	// Best-effort log/event collection on every exit path from here (including
504. 	// image-pull failure) — DESIGN §6.5. No-op when nothing is configured.
505. 	defer e.collectDeploymentLogs(ctx, t, s, p, started)
506. 	fetchStart := time.Now()
507. 	perr := dc.Pull(ctx, t, rc)
508. 	sl.emit(ctx, "FETCH", fetchStart)
509. 	if perr != nil {
510. 		return nil, perr
511. 	}
512. 	if cur, err := dc.CurrentImageID(ctx, t, rc); err == nil && cur != "" {
513. 		oldImage = cur
514. 	}
515. 	runErr := sl.timed(ctx, "START", func() error { return dc.Start(ctx, t, rc) }) // rm -f old + run new
516. 	if runErr == nil {
517. 		runErr = sl.timed(ctx, "HEALTH", func() error {
518. 			return RunHealthCheck(ctx, t, &s.HealthCheck, p.Root, rc.Env)
519. 		})
520. 	}
521. 	if runErr != nil {
522. 		if !s.Strategy.EffectiveRollback() || oldImage == "" {
523. 			// §10.2: record last_operation=failed so Read reports drift even when no
524. 			// rollback is performed (rollback disabled or previous image unknown).
525. 			// Record at the previous version if known, else the attempted version so
526. 			// a fresh docker failure still persists failed state (evaluator iter5 item 2).
527. 			failVer := prev
528. 			if failVer == "" {
529. 				failVer = s.Artifact.Version
530. 			}
531. 			fmErr := e.dockerFinalizeFailed(ctx, sl, t, s, p, failVer, oldImage, started)
532. 			out := fmt.Errorf("%w; no docker rollback performed (prev image unknown or rollback disabled)", runErr)
533. 			if fmErr != nil {
534. 				return nil, coded("ERR_CONNECT", host, "FINALIZE",
535. 					fmt.Errorf("%v; failed-manifest write error: %v", out, fmErr))
536. 			}
537. 			return nil, out
538. 		}
539. 		rbStart := time.Now()
540. 		rerr := dc.RunNew(ctx, t, rc, oldImage)
541. 		if rerr == nil {
542. 			rerr = RunHealthCheck(ctx, t, &s.HealthCheck, p.Root, rc.Env)
543. 		}
544. 		sl.emit(ctx, "ROLLBACK", rbStart)
545. 		if rerr != nil {
546. 			// §10.6: persist a failed manifest before surfacing ERR_ROLLBACK_FAILED.
547. 			// When the old container exists but no prior manifest does (prev==""),
548. 			// record at the attempted version so the failed state is still persisted
549. 			// (evaluator iter6 item 2).
550. 			failVer := prev
551. 			if failVer == "" {
552. 				failVer = s.Artifact.Version
553. 			}
554. 			fmErr := e.dockerFinalizeFailed(ctx, sl, t, s, p, failVer, oldImage, started)
555. 			detail := fmt.Errorf("MACHINE IN UNKNOWN STATE host=%s — manual intervention required; deploy: %v; rollback: %v", host, runErr, rerr)
556. 			if fmErr != nil {
557. 				detail = fmt.Errorf("%v; failed-manifest write error: %v", detail, fmErr)
558. 			}
559. 			return nil, coded("ERR_ROLLBACK_FAILED", host, "ROLLBACK", detail)
560. 		}
561. 		// §10.2/§10.4: the container is back on the previous image and running.
562. 		// Persist a rolled_back manifest at the previous version (image id = the
563. 		// restored image) so Read reports the restored state instead of treating the
564. 		// resource as absent — mirroring the file-based rollback (rollbackSingle) and
565. 		// the docker failed-rollback branch, both of which persist a manifest. A
566. 		// FINALIZE failure here leaves the machine restored but unrecorded, so it is
567. 		// surfaced as ERR_ROLLBACK_FAILED (UNKNOWN STATE) exactly like the file path.
568. 		// Skipped when no previous version is known (unmanaged container): there is
569. 		// no version to record.
570. 		if prev != "" {
571. 			rm := &Manifest{Schema: 1, App: s.Metadata.Name, Pattern: string(s.Pattern.Type),
572. 				CurrentVersion: prev, CurrentRelease: "docker://" + rc.Spec.Pattern.ContainerName,
573. 				ProviderVersion: ProviderVersion,
574. 				Extra:           map[string]string{"image_id": oldImage},
575. 				LastOperation: LastOp{Type: "deploy", Result: "rolled_back",
576. 					Started: started.Format(time.RFC3339), Finished: time.Now().UTC().Format(time.RFC3339)},
577. 			}
578. 			if werr := sl.timed(ctx, "FINALIZE", func() error {
579. 				if derr := ensureDir(ctx, t, p.Root); derr != nil {
580. 					return derr
581. 				}
582. 				return WriteManifest(ctx, t, p, rm)
583. 			}); werr != nil {
584. 				return nil, coded("ERR_ROLLBACK_FAILED", host, "ROLLBACK",
585. 					fmt.Errorf("MACHINE IN UNKNOWN STATE host=%s — restored to previous image %s but manifest write failed: %v; deploy error: %v",
586. 						host, short(oldImage), werr, runErr))
587. 			}
588. 		}
589. 		return nil, fmt.Errorf("%w; rolled back to previous image %s", runErr, short(oldImage))
590. 	}
591. 	newImage, _ := dc.CurrentImageID(ctx, t, rc)
592. 	nm := &Manifest{Schema: 1, App: s.Metadata.Name, Pattern: string(s.Pattern.Type),
593. 		CurrentVersion: s.Artifact.Version, PreviousVersion: prev,
594. 		CurrentRelease:  "docker://" + rc.Spec.Pattern.ContainerName,
595. 		ProviderVersion: ProviderVersion,
596. 		Extra:           map[string]string{"image_id": newImage},
597. 		LastOperation: LastOp{Type: "deploy", Result: "success",
598. 			Started: started.Format(time.RFC3339), Finished: time.Now().UTC().Format(time.RFC3339)},
599. 	}
600. 	// A FINALIZE failure means the new container is running but its manifest was
601. 	// not persisted — the deploy is NOT durably recorded, so fail closed instead
602. 	// of reporting success (evaluator item 9).
603. 	if ferr := sl.timed(ctx, "FINALIZE", func() error {
604. 		if err := ensureDir(ctx, t, p.Root); err != nil {
605. 			return err
606. 		}
607. 		return WriteManifest(ctx, t, p, nm)
608. 	}); ferr != nil {
609. 		return nil, coded("ERR_CONNECT", host, "FINALIZE", ferr)
610. 	}
611. 	st, _ := dc.Status(ctx, t, rc)
612. 	return statusFrom(nm, host, st), nil
613. }
