616. // §10.2/§10.6) recording last_operation.result=failed. The manifest write is
617. // emitted as a structured FINALIZE step (evaluator iter5 item 3).
618. func (e *Engine) dockerFinalizeFailed(ctx context.Context, sl stepLogger, t transport.Transport, s *spec.Deployment,
619. 	p layout.Paths, prev, prevImage string, started time.Time) error {
620. 	if prev == "" {
621. 		return nil
622. 	}
623. 	m := &Manifest{Schema: 1, App: s.Metadata.Name, Pattern: string(s.Pattern.Type),
624. 		CurrentVersion: prev, CurrentRelease: "docker://" + s.Pattern.ContainerName,
625. 		ProviderVersion: ProviderVersion,
626. 		Extra:           map[string]string{"image_id": prevImage},
627. 		LastOperation: LastOp{Type: "deploy", Result: "failed",
628. 			Started: started.Format(time.RFC3339), Finished: time.Now().UTC().Format(time.RFC3339)},
629. 	}
630. 	if err := sl.timed(ctx, "FINALIZE", func() error {
631. 		if derr := ensureDir(ctx, t, p.Root); derr != nil {
632. 			return derr
633. 		}
634. 		return WriteManifest(ctx, t, p, m)
635. 	}); err != nil {
636. 		e.warnf("docker failed-manifest write on %s: %v", t.Host(), err)
637. 		return err
638. 	}
639. 	return nil
