105. func validateArtifact(a *Artifact, p PatternType) error {
106. 	switch a.Type {
107. 	case ArtifactZip, ArtifactNupkg, ArtifactDocker:
108. 	default:
109. 		return vErr("artifact.type: %q not one of zip|nupkg|docker_image", a.Type)
110. 	}
111. 	if !reVersion.MatchString(a.Version) {
112. 		return vErr("artifact.version: required, must match %s", reVersion.String())
113. 	}
114. 	// artifact × pattern (DESIGN §14)
115. 	if a.Type == ArtifactDocker && p != PatternDockerCont {
116. 		return vErr("artifact.type docker_image only valid with pattern docker_container")
117. 	}
118. 	if a.Type != ArtifactDocker && p == PatternDockerCont {
119. 		return vErr("pattern docker_container requires artifact.type docker_image")
120. 	}
121. 	if a.Type != ArtifactDocker {
122. 		if !reChecksum.MatchString(a.Checksum) {
123. 			return vErr(`artifact.checksum: required, format "sha256:<64 hex>"`)
124. 		}
125. 	} else if a.Checksum != "" {
126. 		return vErr("artifact.checksum: forbidden for docker_image (use source.digest)")
127. 	}
128. 	switch a.FetchMode {
129. 	case "", "target_pull", "runner_push":
130. 	default:
131. 		return vErr("artifact.fetch_mode: %q not one of target_pull|runner_push", a.FetchMode)
132. 	}
133. 	s := &a.Source
134. 	switch s.Type {
135. 	case "http":
136. 		if s.URL == "" {
137. 			return vErr("artifact.source.url: required for http")
138. 		}
139. 	case "file":
140. 		if s.Path == "" {
141. 			return vErr("artifact.source.path: required for file")
142. 		}
143. 		if a.FetchMode == "target_pull" {
144. 			return vErr("artifact.fetch_mode: target_pull invalid with file source")
145. 		}
146. 	case "nuget_feed":
147. 		if s.FeedURL == "" || s.PackageID == "" {
148. 			return vErr("artifact.source: feed_url and package_id required for nuget_feed")
149. 		}
150. 	case "docker_registry":
151. 		if a.Type != ArtifactDocker {
152. 			return vErr("artifact.source.type docker_registry requires artifact.type docker_image")
153. 		}
154. 		if s.Image == "" {
155. 			return vErr("artifact.source.image: required for docker_registry")
156. 		}
157. 	default:
158. 		return vErr("artifact.source.type: %q not one of http|file|nuget_feed|docker_registry", s.Type)
159. 	}
160. 	if err := requireEnv(s.Auth.TokenEnv, "artifact.source.auth.token_env"); err != nil {
161. 		return err
162. 	}
163. 	if err := requireEnv(s.Auth.PasswordEnv, "artifact.source.auth.password_env"); err != nil {
164. 		return err
165. 	}
166. 	return nil
167. }
