1. package engine
2. 
3. import (
4. 	"context"
5. 	"strings"
6. 	"testing"
7. 
8. 	"github.com/smartpcr/terraform-provider-labdeploy/internal/spec"
9. 	"github.com/smartpcr/terraform-provider-labdeploy/internal/transport"
10. )
11. 
12. // dockerNode embeds a fakeHost and answers the §9.6 docker D-step scripts
13. // (pull/inspect/run/stop) against a tiny in-memory container state; all other
14. // scripts (connect/preflight/lock/manifest) delegate to the embedded fake.
15. type dockerNode struct {
16. 	*fakeHost
17. 	image         string   // current container image id ("" ⇒ container absent)
18. 	runImage      string   // image id a normal (new-ref) docker run switches the container to
19. 	rollbackImage string   // image id a rollback run (ref == this) switches the container to
20. 	pullErr       bool
21. 	runErr        bool     // docker run fails for BOTH the new ref and the rollback ref
22. 	runScripts    []string // every `docker run` script, in order (new ref then rollback ref)
23. }
24. 
25. func (n *dockerNode) Exec(ctx context.Context, c transport.Cmd) (transport.Result, error) {
26. 	s := c.Script
27. 	switch {
28. 	case strings.Contains(s, "docker pull"):
29. 		if n.pullErr {
30. 			return transport.Result{ExitCode: 40, Stderr: "pull failed"}, nil
31. 		}
32. 		return ok(""), nil
33. 	case strings.Contains(s, "docker inspect") && strings.Contains(s, "{{.Image}}"):
34. 		return ok(n.image), nil
35. 	case strings.Contains(s, "docker inspect") && strings.Contains(s, "{{.State.Running}}"):
36. 		if n.image == "" {
37. 			return ok("not_installed"), nil
38. 		}
39. 		return ok("running"), nil
40. 	case strings.Contains(s, "docker run"):
41. 		n.runScripts = append(n.runScripts, s)
42. 		if n.runErr {
43. 			return transport.Result{ExitCode: 44, Stderr: "run failed"}, nil
44. 		}
45. 		// Reflect the image the container now runs: a rollback run (ref == the
46. 		// recorded old image id) restores rollbackImage; a normal run switches to
47. 		// runImage. This lets healthGate distinguish new-vs-restored by n.image.
48. 		switch {
49. 		case n.rollbackImage != "" && strings.Contains(s, n.rollbackImage):
50. 			n.image = n.rollbackImage
51. 		case n.runImage != "":
52. 			n.image = n.runImage
53. 		}
54. 		return ok(""), nil
55. 	case strings.Contains(s, "docker stop"):
56. 		return ok(""), nil
57. 	}
58. 	return n.fakeHost.Exec(ctx, c)
59. }
60. 
61. // TestDockerRollbackFailedNoManifest covers evaluator iter6 item 2 / DESIGN
62. // §10.6: a docker update failure where an UNMANAGED old container exists
63. // (old image id present) but NO prior manifest does (prev==""), and the
64. // rollback to the old image also fails. The failed manifest must still be
65. // persisted (recorded at the ATTEMPTED version) and ERR_ROLLBACK_FAILED
66. // returned — the old bug passed empty prev to dockerFinalizeFailed which no-op'd.
67. func TestDockerRollbackFailedNoManifest(t *testing.T) {
68. 	n := &dockerNode{fakeHost: newFakeHost("lab-01"), image: "sha256:oldimg", runErr: true}
69. 	eng := New()
70. 	eng.NewTransport = func(tg *spec.Target, host string) (transport.Transport, error) { return n, nil }
71. 
72. 	_, err := eng.Deploy(context.Background(), dockerSpec(t, "2.0.0"))
73. 	var ce *CodedError
74. 	if !asCoded(err, &ce) || ce.Code != "ERR_ROLLBACK_FAILED" {
75. 		t.Fatalf("want ERR_ROLLBACK_FAILED, got %v", err)
76. 	}
77. 	if !strings.Contains(err.Error(), "MACHINE IN UNKNOWN STATE host=lab-01") {
78. 		t.Fatalf("want MACHINE IN UNKNOWN STATE host=lab-01 detail, got: %v", err)
79. 	}
80. 	m := string(n.fakeHost.files[`C:\deploy\sample-svc\manifest.json`])
81. 	if m == "" {
82. 		t.Fatalf("docker rollback failure with no prior manifest must still persist a failed manifest; none written (log=%v)", n.fakeHost.log)
83. 	}
84. 	if !strings.Contains(m, `"current_version": "2.0.0"`) || !strings.Contains(m, `"result": "failed"`) {
85. 		t.Fatalf("failed manifest must record the attempted version 2.0.0 with result=failed: %s", m)
86. 	}
87. }
88. 
89. // dockerSpec is a minimal docker_container Deployment at the given version.
90. func dockerSpec(t *testing.T, version string) *spec.Deployment {
91. 	t.Helper()
92. 	t.Setenv("LABDEPLOY_PASSWORD", "pw")
93. 	y := `
94. apiVersion: labdeploy/v1
95. kind: Deployment
96. metadata: { name: sample-svc }
97. target:
98.   transport: winrm
99.   hosts: ["lab-01"]
100.   os: windows
101.   credentials: { username: u, password_env: LABDEPLOY_PASSWORD }
