663. // collectDeploymentLogs pulls the configured log globs and windows event logs
664. // from the target into a run-specific local dir (DESIGN §6.5 logs.paths /
665. // logs.windows_event_logs; events `since` = operation start). Relative globs
666. // resolve under the app's shared dir (`<app>/shared/`, DESIGN §6.5:339).
667. // Best-effort: failures are surfaced as warnings, never fail the operation.
668. func (e *Engine) collectDeploymentLogs(ctx context.Context, t transport.Transport,
669. 	s *spec.Deployment, p layout.Paths, started time.Time) {
670. 	if len(s.Logs.Paths) == 0 && len(s.Logs.WindowsEventLogs) == 0 {
671. 		return
672. 	}
673. 	dest := filepath.Join("labdeploy-logs", fmt.Sprintf("%s-%d", s.Metadata.Name, started.Unix()))
674. 	if len(s.Logs.Paths) > 0 {
675. 		globs := resolveTargetGlobs(t.OS(), p.Shared, s.Logs.Paths)
676. 		if _, w := logs.CollectFiles(ctx, t, globs, filepath.Join(dest, "logs")); len(w) > 0 {
677. 			for _, x := range w {
678. 				e.warnf("%s", x)
679. 			}
680. 		}
681. 	}
682. 	if len(s.Logs.WindowsEventLogs) > 0 {
683. 		if _, w := logs.CollectEventLogs(ctx, t, s.Logs.WindowsEventLogs, started, filepath.Join(dest, "events")); len(w) > 0 {
684. 			for _, x := range w {
685. 				e.warnf("%s", x)
686. 			}
687. 		}
688. 	}
689. }
690. 
691. // resolveTargetGlobs resolves each glob against base on the target: absolute
692. // globs pass through unchanged; relative globs are joined under base using the
693. // target OS separator. Used for deployment logs.paths and TestRun collect.logs
694. // (`app_shared_of`).
695. func resolveTargetGlobs(os spec.OSKind, base string, globs []string) []string {
696. 	out := make([]string, 0, len(globs))
697. 	for _, g := range globs {
698. 		if isAbsTargetPath(os, g) {
699. 			out = append(out, g)
700. 			continue
701. 		}
702. 		if os == spec.OSWindows {
703. 			out = append(out, base+`\`+strings.ReplaceAll(strings.TrimLeft(g, `\/`), "/", `\`))
704. 		} else {
705. 			out = append(out, base+"/"+strings.TrimLeft(g, "/"))
706. 		}
707. 	}
708. 	return out
709. }
710. 
711. func isAbsTargetPath(os spec.OSKind, g string) bool {
712. 	if os == spec.OSWindows {
713. 		return strings.HasPrefix(g, `\\`) || (len(g) >= 2 && g[1] == ':')
714. 	}
715. 	return strings.HasPrefix(g, "/")
716. }
