718. // releaseCtx builds the pattern context for a FORWARD operation, whose release
719. // version is the spec's desired artifact version (paths and env agree).
720. func releaseCtx(s *spec.Deployment, p layout.Paths) pattern.ReleaseCtx {
721. 	return releaseCtxVersion(s, p, s.Artifact.Version)
722. }
723. 
724. // releaseCtxVersion builds the pattern context for the release identified by
725. // `version` — the version actually being (re)configured on the target, which is
726. // NOT necessarily s.Artifact.Version. layout.Paths carries only the version-
727. // independent `current` junction (LD_RELEASE_DIR), so the running version has to
728. // be threaded in explicitly. Rollback/restore MUST pass the PREVIOUS version so
729. // LD_VERSION (and ReleaseCtx.Version) reflect the running release per DESIGN
730. // §9.1: windows_service bakes rc.Env — including LD_VERSION — into the SCM
731. // Environment value, so a restored previous-version service would otherwise come
732. // up advertising the failed/new version and its /health body `v=<LD_VERSION>`
733. // (§18) would be wrong.
734. func releaseCtxVersion(s *spec.Deployment, p layout.Paths, version string) pattern.ReleaseCtx {
735. 	nodePort := 0
736. 	if s.Pattern.Type == spec.PatternNodeWebApp {
737. 		nodePort = s.Pattern.Port
738. 	}
739. 	env := layout.MergeEnv(layout.BuiltinEnv(s.Metadata.Name, version, p, nodePort), s.Environment)
740. 	return pattern.ReleaseCtx{App: s.Metadata.Name, Version: version,
741. 		P: p, Spec: s, Env: env}
742. }
