1086. // releaseCached reports whether the on-host release marker proves the wanted
1087. // version is already fully extracted. It parses `.labdeploy-release.json` and
1088. // requires ALL of {version, sha256, extracted_at} to be present and for version
1089. // + sha256 to match the request; a missing, malformed, or partially-written
1090. // marker is treated as "not cached" so the release is re-fetched/extracted.
1091. func (e *Engine) releaseCached(ctx context.Context, t transport.Transport, p layout.Paths, wantVersion, wantChecksum string) (bool, error) {
1092. 	marker := p.Release + sepFor(t.OS()) + releaseMarker
1093. 	raw, ok, err := readSmallFile(ctx, t, marker)
1094. 	if err != nil || !ok {
1095. 		return false, err
1096. 	}
1097. 	var m struct {
1098. 		Version     string `json:"version"`
1099. 		SHA256      string `json:"sha256"`
1100. 		ExtractedAt string `json:"extracted_at"`
1101. 	}
1102. 	if jerr := json.Unmarshal([]byte(raw), &m); jerr != nil {
1103. 		return false, nil // malformed marker ⇒ re-stage rather than trust it
1104. 	}
1105. 	if m.Version == "" || m.SHA256 == "" || m.ExtractedAt == "" {
1106. 		return false, nil // incomplete marker ⇒ re-stage
1107. 	}
1108. 	return m.Version == wantVersion && m.SHA256 == wantChecksum, nil
1109. }
