1317. // ReadStatus refreshes state. (nil, nil) ⇒ resource gone (manifest absent).
1318. func (e *Engine) ReadStatus(ctx context.Context, s *spec.Deployment) (*Status, error) {
1319. 	host := strings.ToLower(s.Target.Hosts[0])
1320. 	t, err := e.NewTransport(&s.Target, host)
1321. 	if err != nil {
1322. 		return nil, err
1323. 	}
1324. 	if err := t.Connect(ctx); err != nil {
1325. 		return nil, wrapTransportErr(err, host, "CONNECT") // unreachable ≠ deleted (DESIGN §10.4)
1326. 	}
1327. 	defer t.Close()
1328. 	p := layout.NewPaths(s.Target.OS, s.Pattern.EffectiveInstallRoot(s.Target.OS), s.Metadata.Name, s.Artifact.Version)
1329. 	m, err := ReadManifest(ctx, t, p)
1330. 	if err != nil {
1331. 		return nil, coded("ERR_CONNECT", host, "PREFLIGHT", err)
1332. 	}
1333. 	present, deployedVer, warn := ReconcileManifest(m)
1334. 	if !present {
1335. 		return nil, nil
1336. 	}
1337. 	if warn != "" {
1338. 		e.warnf("%s", warn)
1339. 	}
1340. 	pat, err := pattern.For(s.Pattern.Type)
1341. 	if err != nil {
1342. 		return nil, err
1343. 	}
1344. 	rp := layout.NewPaths(s.Target.OS, s.Pattern.EffectiveInstallRoot(s.Target.OS), s.Metadata.Name, m.CurrentVersion)
1345. 	// Read reports the CURRENT deployed state, so the pattern context's version
1346. 	// MUST be the manifest's current_version — NOT s.Artifact.Version (the desired
1347. 	// version). Otherwise console_app.Status, which compares the on-host
1348. 	// `.labdeploy-release.json` marker version against ReleaseCtx.Version, would
1349. 	// falsely report drift whenever a plan desires a version different from what
1350. 	// is deployed (evaluator iter2 item 1). Marker/manifest agreement ⇒ n/a.
1351. 	st, serr := pat.Status(ctx, t, releaseCtxVersion(s, rp, m.CurrentVersion))
1352. 	if serr != nil {
1353. 		// A failed status probe is a loud refresh failure, not an empty/healthy
1354. 		// service status (evaluator item 5 / DESIGN §10.4).
1355. 		return nil, wrapTransportErr(serr, host, "READ")
1356. 	}
1357. 	out := statusFrom(m, host, st)
1358. 	out.DeployedVersion = deployedVer
1359. 	if s.Pattern.Type == spec.PatternClusterGeneric {
1360. 		out.Hosts = lowerAll(s.Target.Hosts)
1361. 	}
1362. 	return out, nil
1363. }
