1. // Package engine orchestrates the deployment state machine (DESIGN §10).
2. package engine
3. 
4. import (
5. 	"context"
6. 	"encoding/json"
7. 	"errors"
8. 	"fmt"
9. 	"os"
10. 	"path/filepath"
11. 	"sort"
12. 	"strings"
13. 	"time"
14. 
15. 	"github.com/hashicorp/terraform-plugin-log/tflog"
16. 
17. 	"github.com/smartpcr/terraform-provider-labdeploy/internal/artifact"
18. 	"github.com/smartpcr/terraform-provider-labdeploy/internal/layout"
19. 	"github.com/smartpcr/terraform-provider-labdeploy/internal/logs"
20. 	"github.com/smartpcr/terraform-provider-labdeploy/internal/pattern"
21. 	"github.com/smartpcr/terraform-provider-labdeploy/internal/spec"
22. 	"github.com/smartpcr/terraform-provider-labdeploy/internal/transport"
23. )
24. 
25. const ProviderVersion = "0.1.0"
26. 
27. // Status is what the resource surfaces as computed attributes (DESIGN §5.2).
28. type Status struct {
29. 	DeployedVersion string
30. 	PreviousVersion string
31. 	ReleasePath     string
32. 	ServiceStatus   string
33. 	Hosts           []string
34. }
35. 
36. type Engine struct {
37. 	// NewTransport is swappable for fake-transport unit tests (DESIGN §17).
38. 	NewTransport func(t *spec.Target, host string) (transport.Transport, error)
39. 	Warnings     []string
40. }
41. 
42. func New() *Engine { return &Engine{NewTransport: transport.NewTransport} }
43. 
44. func (e *Engine) warnf(format string, a ...interface{}) {
45. 	e.Warnings = append(e.Warnings, fmt.Sprintf(format, a...))
46. }
47. 
48. // warnOnce appends msg only if it is not already present. It exists so
49. // per-host gates (e.g. the DESIGN §11 insecure-transport notices in preflight,
50. // which the cluster path runs for every node) surface EXACTLY ONE WARN diag per
51. // apply rather than one per host.
52. func (e *Engine) warnOnce(msg string) {
53. 	for _, w := range e.Warnings {
54. 		if w == msg {
55. 			return
56. 		}
57. 	}
58. 	e.Warnings = append(e.Warnings, msg)
59. }
60. 
61. // InsecureTransportWarnings returns the DESIGN §11 lab-insecure transport WARN
62. // messages for a spec: an unpinned SSH host_key ("" ⇒ accept any host key) and/or
63. // WinRM insecure_skip_verify=true (TLS certificate verification disabled). It is the
64. // SINGLE SOURCE OF TRUTH for those message strings, consumed both by the apply-time
65. // preflight (deduped to exactly one per apply via warnOnce) and by the provider surface
66. // tests that assert the framework WARN diagnostic wording. A secure spec returns nil.
67. func InsecureTransportWarnings(s *spec.Deployment) []string {
68. 	var out []string
69. 	if s.Target.Transport == spec.TransportSSH && s.Target.SSH.HostKey == "" {
70. 		out = append(out, "ssh.host_key not pinned — accepting any host key (lab default; DESIGN §11)")
71. 	}
72. 	if s.Target.Transport == spec.TransportWinRM &&
73. 		s.Target.WinRM.InsecureSkipVerify != nil && *s.Target.WinRM.InsecureSkipVerify {
74. 		out = append(out, "winrm.insecure_skip_verify=true — TLS certificate verification disabled (lab default; DESIGN §11)")
75. 	}
76. 	return out
77. }
78. 
79. // warnInsecureTransport emits the DESIGN §11 lab-insecure transport notices EXACTLY
80. // ONCE per apply. The messages omit the host so warnOnce dedups them to a single notice
81. // even though the cluster path preflights every node; ReadStatus never calls preflight,
82. // so a plan/refresh stays silent.
83. func (e *Engine) warnInsecureTransport(s *spec.Deployment) {
84. 	for _, w := range InsecureTransportWarnings(s) {
85. 		e.warnOnce(w)
86. 	}
87. }
88. 
89. // stepLogger emits the DESIGN §8.5/§15 structured step record. EVERY fixed step
90. // (VALIDATE CONNECT PREFLIGHT LOCK FETCH CHECKSUM STAGE EXTRACT RENDER CONFIGURE
91. // STOP SWITCH START HEALTH FINALIZE PRUNE UNLOCK, plus ROLLBACK/FORCE_KILL/
92. // MOVE_GROUP) is logged through tflog carrying app/host/step/version and a
93. // numeric duration_ms. A step is emitted whether it succeeded or failed — a
94. // failed step is still an executed step — so the log is a faithful trace of the
95. // state machine. Conditional steps (FETCH/CHECKSUM/EXTRACT when a release is
96. // cached) are simply never entered, so they never appear.
97. type stepLogger struct {
98. 	app     string
99. 	host    string
100. 	version string
101. }
102. 
103. func newStepLogger(s *spec.Deployment, host string) stepLogger {
104. 	return stepLogger{app: s.Metadata.Name, host: strings.ToLower(host), version: s.Artifact.Version}
105. }
106. 
107. // forHost returns a copy of the logger bound to a different host (cluster nodes
108. // share the same app/version but log per-node).
109. func (sl stepLogger) forHost(host string) stepLogger {
110. 	sl.host = strings.ToLower(host)
111. 	return sl
112. }
113. 
114. // emit writes one structured step record measuring elapsed time from start.
115. func (sl stepLogger) emit(ctx context.Context, step string, start time.Time) {
116. 	tflog.Info(ctx, "deploy step", map[string]interface{}{
117. 		"app":         sl.app,
118. 		"host":        sl.host,
119. 		"step":        step,
120. 		"version":     sl.version,
121. 		"duration_ms": time.Since(start).Milliseconds(),
122. 	})
123. }
124. 
125. // timed runs fn and emits the step record afterward regardless of outcome.
126. func (sl stepLogger) timed(ctx context.Context, step string, fn func() error) error {
127. 	start := time.Now()
128. 	err := fn()
129. 	sl.emit(ctx, step, start)
130. 	return err
131. }
132. 
133. // isChecksumErr reports whether err (or any error it wraps) is a coded
134. // ERR_CHECKSUM_MISMATCH, so the caller can record the CHECKSUM step as the
135. // failing step even though verification happens inside the fetch.
136. func isChecksumErr(err error) bool {
137. 	if err == nil {
138. 		return false
139. 	}
140. 	var ce *CodedError
141. 	if errors.As(err, &ce) {
142. 		return ce.Code == "ERR_CHECKSUM_MISMATCH"
143. 	}
144. 	return false
145. }
146. 
147. // Update is the entry point for a resource Update (DESIGN §10.2). When the desired
148. // spec leaves the artifact (version + checksum) unchanged from prior — a
149. // configuration-only change — Deploy's idempotency short-circuit (§10.1 step 2)
150. // would skip CONFIGURE and silently drop the new mutable settings while Terraform
151. // records them. For a single-target windows_service that case is routed through the
152. // transactional, rollback-safe Reconfigure path so the change is actually applied.
153. // Every other case (a new/changed artifact, or a pattern/topology Reconfigure does
154. // not cover) falls through to Deploy, which is itself idempotent.
155. func (e *Engine) Update(ctx context.Context, s, prior *spec.Deployment) (*Status, error) {
156. 	if reconfigurable(s, prior) {
157. 		st, err := e.Reconfigure(ctx, s, prior)
158. 		if err != nil {
159. 			return nil, err
160. 		}
161. 		if st != nil {
162. 			return st, nil
163. 		}
164. 		// Reconfigure returns (nil, nil) when nothing is deployed yet (no manifest).
165. 		// A configuration-only "update" against an absent deployment is meaningless;
166. 		// fall through to a full Deploy rather than returning a nil status that the
167. 		// caller would dereference.
168. 	}
169. 	return e.Deploy(ctx, s)
170. }
171. 
172. // reconfigurable reports whether a same-artifact configuration change should be
173. // applied via Reconfigure rather than Deploy. Reconfigure is single-host and
174. // defined for the SCM-registered service patterns (windows_service and the
175. // node_web_app / dotnet_api patterns that delegate their Configure/Stop/Start/
176. // Status verbs to WindowsService); anything else defers to Deploy.
177. // artifactUnchanged gates it so version upgrades always deploy.
178. //
179. // node_web_app is included even when install_deps toggles: Reconfigure runs the
180. // pattern Preflight (node/dotnet tool checks) and, for node_web_app, re-runs
181. // InstallDeps (`npm ci --omit=dev`) at the pre-activation point, so a same-
182. // artifact install_deps=false→true change actually installs dependencies instead
183. // of being swallowed by Deploy's unchanged-artifact idempotency short-circuit.
184. func reconfigurable(s, prior *spec.Deployment) bool {
185. 	if prior == nil || s == nil {
186. 		return false
187. 	}
188. 	switch s.Pattern.Type {
189. 	case spec.PatternWindowsService, spec.PatternNodeWebApp, spec.PatternDotnetAPI:
190. 		// applied via Preflight + Stop/Configure/Start (+ node InstallDeps) on the
191. 		// deployed release, all handled by Reconfigure.
192. 	default:
193. 		return false
194. 	}
195. 	if len(s.Target.Hosts) != 1 {
196. 		return false
197. 	}
198. 	return artifactUnchanged(s, prior)
199. }
200. 
201. // artifactUnchanged reports whether two specs point at the same artifact — the
202. // signal that a change is configuration-only.
203. func artifactUnchanged(s, prior *spec.Deployment) bool {
204. 	return s.Artifact.Version == prior.Artifact.Version &&
205. 		s.Artifact.Checksum == prior.Artifact.Checksum
206. }
207. 
208. // Deploy is the entry point for Create and Update (DESIGN §10.1/§10.2).
209. func (e *Engine) Deploy(ctx context.Context, s *spec.Deployment) (*Status, error) {
210. 	if s.Pattern.Type == spec.PatternClusterGeneric {
211. 		return e.deployCluster(ctx, s)
212. 	}
213. 	return e.deploySingle(ctx, s)
214. }
215. 
216. func (e *Engine) deploySingle(ctx context.Context, s *spec.Deployment) (*Status, error) {
217. 	host := strings.ToLower(s.Target.Hosts[0])
218. 	sl := newStepLogger(s, host)
219. 	vstart := time.Now()
220. 	t, err := e.NewTransport(&s.Target, host)
221. 	if err != nil {
222. 		sl.emit(ctx, "VALIDATE", vstart)
223. 		return nil, coded("ERR_SPEC_INVALID", host, "VALIDATE", err)
224. 	}
225. 	pat, verr := pattern.For(s.Pattern.Type)
226. 	sl.emit(ctx, "VALIDATE", vstart)
227. 	if verr != nil {
228. 		return nil, coded("ERR_UNSUPPORTED", host, "VALIDATE", verr)
229. 	}
230. 	cstart := time.Now()
231. 	if err := t.Connect(ctx); err != nil {
232. 		sl.emit(ctx, "CONNECT", cstart)
233. 		return nil, wrapTransportErr(err, host, "CONNECT")
234. 	}
235. 	sl.emit(ctx, "CONNECT", cstart)
236. 	defer t.Close()
237. 
238. 	p := layout.NewPaths(s.Target.OS, s.Pattern.EffectiveInstallRoot(s.Target.OS), s.Metadata.Name, s.Artifact.Version)
239. 	rc := releaseCtx(s, p)
240. 
241. 	if err := sl.timed(ctx, "PREFLIGHT", func() error { return e.preflight(ctx, t, s, p, pat, rc) }); err != nil {
242. 		return nil, err
243. 	}
244. 
245. 	lstart := time.Now()
246. 	lk, warn, err := AcquireLock(ctx, t, p, lockOwner(), "deploy", s.Strategy.EffectiveLockTimeout())
247. 	sl.emit(ctx, "LOCK", lstart)
248. 	if err != nil {
249. 		return nil, err
250. 	}
251. 	if warn != "" {
252. 		e.warnf("%s", warn)
253. 	}
254. 	defer func() {
255. 		rctx, cancel := lockCleanupContext(ctx)
256. 		defer cancel()
257. 		ustart := time.Now()
258. 		if rerr := ReleaseLock(rctx, lk); rerr != nil {
259. 			e.warnf("lock release failed on %s: %v", host, rerr)
260. 		}
261. 		sl.emit(ctx, "UNLOCK", ustart)
262. 	}()
263. 
264. 	m, err := ReadManifest(ctx, t, p)
265. 	if err != nil {
266. 		return nil, coded("ERR_CONNECT", host, "PREFLIGHT", err)
267. 	}
268. 
269. 	// Docker never uses staging/junction (DESIGN §9.6).
270. 	if s.Pattern.Type == spec.PatternDockerCont {
271. 		return e.deployDocker(ctx, sl, t, s, p, pat.(*pattern.DockerContainer), rc, m)
272. 	}
273. 
274. 	// Idempotency short-circuit (DESIGN §10.1 step 2).
275. 	if m != nil && m.CurrentVersion == s.Artifact.Version && m.ArtifactChecksum == s.Artifact.Checksum {
276. 		st, serr := pat.Status(ctx, t, rc)
277. 		if serr == nil && (st == "running" || st == "n/a" || st == "online") {
278. 			tflog.Info(ctx, "idempotent no-op: version already deployed and healthy",
279. 				map[string]interface{}{"host": host, "version": s.Artifact.Version})
280. 			return statusFrom(m, host, st), nil
281. 		}
282. 	}
283. 
284. 	prev := ""
285. 	prevChecksum := ""
286. 	if m != nil {
287. 		prev = m.CurrentVersion
288. 		prevChecksum = m.ArtifactChecksum
289. 	}
290. 	started := time.Now().UTC()
291. 	// Best-effort collection of logs.paths + windows_event_logs since operation
292. 	// start, on EVERY exit path from here (success, staging failure, rollback) —
293. 	// DESIGN §6.5. No-op when nothing is configured.
294. 	defer e.collectDeploymentLogs(ctx, t, s, p, started)
295. 
296. 	// STAGE / FETCH / CHECKSUM / EXTRACT / RENDER — no live mutation yet.
297. 	if err := e.stageOnHost(ctx, sl, t, s, p, pat, rc); err != nil {
298. 		return nil, err
299. 	}
300. 
301. 	// SWITCHOVER — from here on, failures trigger rollback (DESIGN §10.3).
302. 	switchErr := e.switchOn(ctx, sl, t, s, p, pat, rc)
303. 	if switchErr == nil {
304. 		switchErr = sl.timed(ctx, "HEALTH", func() error {
305. 			return RunHealthCheck(ctx, t, &s.HealthCheck, p.Current, rc.Env)
306. 		})
307. 	}
308. 	if switchErr != nil {
309. 		return nil, e.rollbackSingle(ctx, sl, t, s, p, pat, prev, prevChecksum, started, switchErr)
310. 	}
311. 
312. 	// FINALIZE + PRUNE (DESIGN §10.1 steps 12–13).
313. 	nm := &Manifest{
314. 		Schema: 1, App: s.Metadata.Name, Pattern: string(s.Pattern.Type),
315. 		CurrentVersion: s.Artifact.Version, PreviousVersion: prev,
316. 		CurrentRelease: p.Release, ArtifactChecksum: s.Artifact.Checksum,
317. 		ProviderVersion: ProviderVersion,
318. 		LastOperation: LastOp{Type: "deploy", Result: "success",
319. 			Started: started.Format(time.RFC3339), Finished: time.Now().UTC().Format(time.RFC3339)},
320. 	}
321. 	ferr := sl.timed(ctx, "FINALIZE", func() error { return WriteManifest(ctx, t, p, nm) })
322. 	if ferr != nil {
323. 		return nil, coded("ERR_CONNECT", host, "FINALIZE", ferr)
324. 	}
325. 	if err := sl.timed(ctx, "PRUNE", func() error { return e.pruneReleases(ctx, t, s, p, nm) }); err != nil {
326. 		e.warnf("prune failed on %s: %v", host, err) // never fails the apply
327. 	}
328. 	st, _ := pat.Status(ctx, t, rc)
329. 	return statusFrom(nm, host, st), nil
330. }
331. 
332. // rollbackSingle implements DESIGN §10.3 for one host. Returns the ORIGINAL
333. // error (annotated) on successful rollback; ERR_ROLLBACK_FAILED otherwise.
334. func (e *Engine) rollbackSingle(ctx context.Context, sl stepLogger, t transport.Transport, s *spec.Deployment,
335. 	p layout.Paths, pat pattern.Pattern, prev, prevChecksum string, started time.Time, orig error) error {
336. 	host := t.Host()
337. 	if !s.Strategy.EffectiveRollback() {
338. 		// §10.2 last row: record last_operation=failed so Read reports drift. A
339. 		// failed-manifest write error must not be swallowed — it is folded into the
340. 		// surfaced error so the caller learns the failed state was not persisted
341. 		// (evaluator item 4). On a FRESH failure (prev=="") the attempted version
342. 		// is recorded so §10.2 persistence still happens instead of no-op'ing on an
343. 		// empty version (evaluator iter5 item 1).
344. 		failVer := prev
345. 		if failVer == "" {
346. 			failVer = s.Artifact.Version
347. 		}
348. 		ferr := e.finalizeFailed(ctx, sl, t, s, p, failVer, started, "failed")
349. 		out := fmt.Errorf("%w; rollback_on_failure=false — target left as-is for inspection", orig)
350. 		if ferr != nil {
351. 			return coded("ERR_CONNECT", host, "FINALIZE",
352. 				fmt.Errorf("%v; failed-manifest write error: %v", out, ferr))
353. 		}
354. 		return out
355. 	}
356. 	rbStart := time.Now()
357. 	if prev == "" {
358. 		// Fresh install failure ⇒ clean the machine (DESIGN §10.3 row 1). Every
359. 		// cleanup action's error is collected: a failed cleanup means the machine
360. 		// is NOT actually clean, so we surface ERR_ROLLBACK_FAILED rather than
361. 		// falsely report a cleaned target (evaluator iter2 item 6).
362. 		rcNew := releaseCtx(s, p)
363. 		rcNew.EmitStep = sl.forHost(host).emit
364. 		var cleanupErrs []error
365. 		if err := pat.Stop(ctx, t, rcNew); err != nil {
366. 			cleanupErrs = append(cleanupErrs, fmt.Errorf("stop: %w", err))
367. 		}
368. 		if err := pat.Uninstall(ctx, t, rcNew, false); err != nil {
369. 			cleanupErrs = append(cleanupErrs, fmt.Errorf("uninstall: %w", err))
370. 		}
371. 		if err := e.removeJunction(ctx, t, p); err != nil {
372. 			cleanupErrs = append(cleanupErrs, fmt.Errorf("junction: %w", err))
373. 		}
374. 		// Remove the release tree THIS op created. For patterns whose hooks run
375. 		// PRE-switch (windows_service post_install), stageOnHost's incomplete-
376. 		// release cleanup already did this; but console_app runs post_install and
377. 		// verify_command POST-switch (DESIGN §9.3), so a fresh console failure
378. 		// reaches here with the release still on disk. Deleting it honors the
379. 		// §10.2 fresh-install contract ("machine clean") for every pattern
380. 		// (evaluator iter2 item 2). Idempotent: removePath no-ops when absent.
381. 		if err := e.removePath(ctx, t, p.Release); err != nil {
382. 			cleanupErrs = append(cleanupErrs, fmt.Errorf("release: %w", err))
383. 		}
384. 		if err := e.removePath(ctx, t, p.Manifest); err != nil {
385. 			cleanupErrs = append(cleanupErrs, fmt.Errorf("manifest: %w", err))
386. 		}
387. 		sl.emit(ctx, "ROLLBACK", rbStart)
388. 		if len(cleanupErrs) > 0 {
389. 			// §10.6: persist a failed manifest recording the unknown state before
390. 			// surfacing ERR_ROLLBACK_FAILED. The fresh cleanup may have removed the
391. 			// manifest, so write one at the attempted (current) version recording
392. 			// last_operation.result=failed; a write failure is folded into the
393. 			// diagnostic so we never claim persistence that did not happen.
394. 			ferr := e.finalizeFailed(ctx, sl, t, s, p, s.Artifact.Version, started, "failed")
395. 			detail := fmt.Errorf("MACHINE IN UNKNOWN STATE host=%s — manual intervention required; deploy error: %v; fresh-install cleanup error: %v",
396. 				host, orig, errors.Join(cleanupErrs...))
397. 			if ferr != nil {
398. 				detail = fmt.Errorf("%v; failed-manifest write error: %v", detail, ferr)
399. 			}
400. 			return coded("ERR_ROLLBACK_FAILED", host, "ROLLBACK", detail)
401. 		}
402. 		return fmt.Errorf("%w; fresh install failed — target cleaned (no service, no junction, no manifest)", orig)
403. 	}
404. 	tflog.Warn(ctx, "deploy failed; rolling back", map[string]interface{}{
405. 		"host": host, "from": s.Artifact.Version, "to": prev, "cause": orig.Error()})
406. 
407. 	pp := layout.NewPaths(s.Target.OS, s.Pattern.EffectiveInstallRoot(s.Target.OS), s.Metadata.Name, prev)
408. 	// Restore the PREVIOUS release: thread `prev` so LD_VERSION/ReleaseCtx.Version
409. 	// reflect the version being brought back up, not the failed s.Artifact.Version
410. 	// (DESIGN §9.1). Otherwise Configure would bake the new version's LD_VERSION
411. 	// into the restored previous-version service's SCM Environment value.
412. 	rcPrev := releaseCtxVersion(s, pp, prev)
413. 	rcPrev.EmitStep = sl.forHost(host).emit
414. 	rb := func() error {
415. 		if err := sl.timed(ctx, "STOP", func() error { return pat.Stop(ctx, t, rcPrev) }); err != nil {
416. 			return err
417. 		}
418. 		if err := sl.timed(ctx, "SWITCH", func() error { return e.switchJunction(ctx, t, pp) }); err != nil {
419. 			return err
420. 		}
421. 		if err := sl.timed(ctx, "CONFIGURE", func() error { return pat.Configure(ctx, t, rcPrev) }); err != nil {
422. 			return err
423. 		}
424. 		if err := sl.timed(ctx, "START", func() error { return pat.Start(ctx, t, rcPrev) }); err != nil {
425. 			return err
426. 		}
427. 		return sl.timed(ctx, "HEALTH", func() error {
428. 			return RunHealthCheck(ctx, t, &s.HealthCheck, pp.Current, rcPrev.Env)
429. 		})
430. 	}
431. 	rerr := rb()
432. 	sl.emit(ctx, "ROLLBACK", rbStart)
433. 	if rerr != nil {
434. 		fmErr := e.finalizeFailed(ctx, sl, t, s, pp, prev, started, "failed")
435. 		detail := fmt.Errorf("MACHINE IN UNKNOWN STATE host=%s — manual intervention required; deploy error: %v; rollback error: %v", host, orig, rerr)
436. 		if fmErr != nil {
437. 			detail = fmt.Errorf("%v; failed-manifest write error: %v", detail, fmErr)
438. 		}
439. 		return coded("ERR_ROLLBACK_FAILED", host, "ROLLBACK", detail)
440. 	}
441. 	// Restore succeeded: persist a manifest reflecting the previous version as the
442. 	// current state, INCLUDING its artifact checksum so the recorded manifest is
443. 	// consistent with what is actually running. A WriteManifest failure leaves the
444. 	// manifest out of sync with the restored machine, so it is surfaced as
445. 	// ERR_ROLLBACK_FAILED rather than silently ignored (evaluator iter2 item 7).
446. 	m := &Manifest{
447. 		Schema: 1, App: s.Metadata.Name, Pattern: string(s.Pattern.Type),
448. 		CurrentVersion: prev, CurrentRelease: pp.Release, ArtifactChecksum: prevChecksum,
449. 		ProviderVersion: ProviderVersion,
450. 		LastOperation: LastOp{Type: "deploy", Result: "rolled_back",
451. 			Started: started.Format(time.RFC3339), Finished: time.Now().UTC().Format(time.RFC3339)},
452. 	}
453. 	if werr := sl.timed(ctx, "FINALIZE", func() error { return WriteManifest(ctx, t, pp, m) }); werr != nil {
454. 		return coded("ERR_ROLLBACK_FAILED", host, "ROLLBACK",
455. 			fmt.Errorf("MACHINE IN UNKNOWN STATE host=%s — restored to %s but manifest write failed: %v; deploy error: %v",
456. 				host, prev, werr, orig))
457. 	}
458. 	return fmt.Errorf("%w; rolled back to %s (healthy)", orig, prev)
459. }
460. 
461. // finalizeFailed persists a manifest recording last_operation.result=<result>
462. // (DESIGN §10.2/§10.6). The manifest write is emitted as a structured FINALIZE
463. // step (every executed fixed step, including failure/rollback occurrences, must
464. // carry app/host/step/version/duration_ms — evaluator iter5 item 3).
465. func (e *Engine) finalizeFailed(ctx context.Context, sl stepLogger, t transport.Transport, s *spec.Deployment,
466. 	p layout.Paths, current string, started time.Time, result string) error {
467. 	if current == "" {
468. 		return nil
469. 	}
470. 	m, _ := ReadManifest(ctx, t, p)
471. 	if m == nil {
472. 		m = &Manifest{Schema: 1, App: s.Metadata.Name, Pattern: string(s.Pattern.Type),
473. 			CurrentVersion: current, CurrentRelease: p.Release, ProviderVersion: ProviderVersion}
474. 	}
475. 	m.LastOperation = LastOp{Type: "deploy", Result: result,
476. 		Started: started.Format(time.RFC3339), Finished: time.Now().UTC().Format(time.RFC3339)}
477. 	if err := sl.timed(ctx, "FINALIZE", func() error { return WriteManifest(ctx, t, p, m) }); err != nil {
478. 		e.warnf("failed-manifest write on %s: %v", t.Host(), err)
479. 		return err
480. 	}
481. 	return nil
482. }
483. 
484. // deployDocker = D-steps (DESIGN §9.6) with image-id rollback. Emits the same
485. // structured step records as the file-based path for its executed steps: FETCH
486. // (image pull), START (rm -f old + run new), HEALTH, FINALIZE (manifest write),
487. // and ROLLBACK on failure — each carrying app/host/step/version/duration_ms.
488. func (e *Engine) deployDocker(ctx context.Context, sl stepLogger, t transport.Transport, s *spec.Deployment,
489. 	p layout.Paths, dc *pattern.DockerContainer, rc pattern.ReleaseCtx, m *Manifest) (*Status, error) {
490. 	host := t.Host()
491. 	sl = sl.forHost(host)
492. 	started := time.Now().UTC()
493. 	if m != nil && m.CurrentVersion == s.Artifact.Version {
494. 		if st, err := dc.Status(ctx, t, rc); err == nil && st == "running" {
495. 			return statusFrom(m, host, st), nil
496. 		}
497. 	}
498. 	prev, oldImage := "", ""
499. 	if m != nil {
500. 		prev = m.CurrentVersion
501. 		oldImage = m.Extra["image_id"]
502. 	}
503. 	// Best-effort log/event collection on every exit path from here (including
504. 	// image-pull failure) — DESIGN §6.5. No-op when nothing is configured.
505. 	defer e.collectDeploymentLogs(ctx, t, s, p, started)
506. 	fetchStart := time.Now()
507. 	perr := dc.Pull(ctx, t, rc)
508. 	sl.emit(ctx, "FETCH", fetchStart)
509. 	if perr != nil {
510. 		return nil, perr
511. 	}
512. 	if cur, err := dc.CurrentImageID(ctx, t, rc); err == nil && cur != "" {
513. 		oldImage = cur
514. 	}
515. 	runErr := sl.timed(ctx, "START", func() error { return dc.Start(ctx, t, rc) }) // rm -f old + run new
516. 	if runErr == nil {
517. 		runErr = sl.timed(ctx, "HEALTH", func() error {
518. 			return RunHealthCheck(ctx, t, &s.HealthCheck, p.Root, rc.Env)
519. 		})
520. 	}
521. 	if runErr != nil {
522. 		if !s.Strategy.EffectiveRollback() || oldImage == "" {
523. 			// §10.2: record last_operation=failed so Read reports drift even when no
524. 			// rollback is performed (rollback disabled or previous image unknown).
525. 			// Record at the previous version if known, else the attempted version so
526. 			// a fresh docker failure still persists failed state (evaluator iter5 item 2).
527. 			failVer := prev
528. 			if failVer == "" {
529. 				failVer = s.Artifact.Version
530. 			}
531. 			fmErr := e.dockerFinalizeFailed(ctx, sl, t, s, p, failVer, oldImage, started)
532. 			out := fmt.Errorf("%w; no docker rollback performed (prev image unknown or rollback disabled)", runErr)
533. 			if fmErr != nil {
534. 				return nil, coded("ERR_CONNECT", host, "FINALIZE",
535. 					fmt.Errorf("%v; failed-manifest write error: %v", out, fmErr))
536. 			}
537. 			return nil, out
538. 		}
539. 		rbStart := time.Now()
540. 		// §9.6 D6 / §10.4: restore the PREVIOUS release. The restored container must
541. 		// advertise the previous version, so rebuild the pattern context at `prev`
542. 		// (LD_VERSION and the -e env baked into `docker run` reflect the running
543. 		// release) rather than reusing the failed new-version rc. Health is rechecked
544. 		// with the same previous-version env.
545. 		rbRC := rc
546. 		if prev != "" {
547. 			rbRC = releaseCtxVersion(s, p, prev)
548. 		}
549. 		rerr := dc.RunNew(ctx, t, rbRC, oldImage)
550. 		if rerr == nil {
551. 			rerr = RunHealthCheck(ctx, t, &s.HealthCheck, p.Root, rbRC.Env)
552. 		}
553. 		sl.emit(ctx, "ROLLBACK", rbStart)
554. 		if rerr != nil {
555. 			// §10.6: persist a failed manifest before surfacing ERR_ROLLBACK_FAILED.
556. 			// When the old container exists but no prior manifest does (prev==""),
557. 			// record at the attempted version so the failed state is still persisted
558. 			// (evaluator iter6 item 2).
559. 			failVer := prev
560. 			if failVer == "" {
561. 				failVer = s.Artifact.Version
562. 			}
563. 			fmErr := e.dockerFinalizeFailed(ctx, sl, t, s, p, failVer, oldImage, started)
564. 			detail := fmt.Errorf("MACHINE IN UNKNOWN STATE host=%s — manual intervention required; deploy: %v; rollback: %v", host, runErr, rerr)
565. 			if fmErr != nil {
566. 				detail = fmt.Errorf("%v; failed-manifest write error: %v", detail, fmErr)
567. 			}
568. 			return nil, coded("ERR_ROLLBACK_FAILED", host, "ROLLBACK", detail)
569. 		}
570. 		// §10.2/§10.4: the container is back on the previous image and running.
571. 		// Persist a rolled_back manifest at the previous version (image id = the
572. 		// restored image) so Read reports the restored state instead of treating the
573. 		// resource as absent — mirroring the file-based rollback (rollbackSingle) and
574. 		// the docker failed-rollback branch, both of which persist a manifest. A
575. 		// FINALIZE failure here leaves the machine restored but unrecorded, so it is
576. 		// surfaced as ERR_ROLLBACK_FAILED (UNKNOWN STATE) exactly like the file path.
577. 		// Skipped when no previous version is known (unmanaged container): there is
578. 		// no version to record.
579. 		if prev != "" {
580. 			rm := &Manifest{Schema: 1, App: s.Metadata.Name, Pattern: string(s.Pattern.Type),
581. 				CurrentVersion: prev, CurrentRelease: "docker://" + rc.Spec.Pattern.ContainerName,
582. 				ProviderVersion: ProviderVersion,
583. 				Extra:           map[string]string{"image_id": oldImage},
584. 				LastOperation: LastOp{Type: "deploy", Result: "rolled_back",
585. 					Started: started.Format(time.RFC3339), Finished: time.Now().UTC().Format(time.RFC3339)},
586. 			}
587. 			if werr := sl.timed(ctx, "FINALIZE", func() error {
588. 				if derr := ensureDir(ctx, t, p.Root); derr != nil {
589. 					return derr
590. 				}
591. 				return WriteManifest(ctx, t, p, rm)
592. 			}); werr != nil {
593. 				return nil, coded("ERR_ROLLBACK_FAILED", host, "ROLLBACK",
594. 					fmt.Errorf("MACHINE IN UNKNOWN STATE host=%s — restored to previous image %s but manifest write failed: %v; deploy error: %v",
595. 						host, short(oldImage), werr, runErr))
596. 			}
597. 		}
598. 		return nil, fmt.Errorf("%w; rolled back to previous image %s", runErr, short(oldImage))
599. 	}
600. 	// D3-equivalent post-run inspect: the recorded image id backs a FUTURE
601. 	// rollback, so a missing/failed inspect means the deploy is NOT durably
602. 	// recorded — fail closed instead of persisting a success manifest with an
603. 	// empty image_id (evaluator iter2 item 1).
604. 	newImage, ierr := dc.CurrentImageID(ctx, t, rc)
605. 	if ierr != nil || strings.TrimSpace(newImage) == "" {
606. 		return nil, coded("ERR_CONNECT", host, "FINALIZE",
607. 			fmt.Errorf("container started but its image id could not be recorded (inspect err=%v, image_id=%q); deploy not durably recorded", ierr, newImage))
608. 	}
609. 	nm := &Manifest{Schema: 1, App: s.Metadata.Name, Pattern: string(s.Pattern.Type),
610. 		CurrentVersion: s.Artifact.Version, PreviousVersion: prev,
611. 		CurrentRelease:  "docker://" + rc.Spec.Pattern.ContainerName,
612. 		ProviderVersion: ProviderVersion,
613. 		Extra:           map[string]string{"image_id": newImage},
614. 		LastOperation: LastOp{Type: "deploy", Result: "success",
615. 			Started: started.Format(time.RFC3339), Finished: time.Now().UTC().Format(time.RFC3339)},
616. 	}
617. 	// A FINALIZE failure means the new container is running but its manifest was
618. 	// not persisted — the deploy is NOT durably recorded, so fail closed instead
619. 	// of reporting success (evaluator item 9).
620. 	if ferr := sl.timed(ctx, "FINALIZE", func() error {
621. 		if err := ensureDir(ctx, t, p.Root); err != nil {
622. 			return err
623. 		}
624. 		return WriteManifest(ctx, t, p, nm)
625. 	}); ferr != nil {
626. 		return nil, coded("ERR_CONNECT", host, "FINALIZE", ferr)
627. 	}
628. 	st, _ := dc.Status(ctx, t, rc)
629. 	return statusFrom(nm, host, st), nil
630. }
631. 
632. // dockerFinalizeFailed persists a failed manifest for the docker path (DESIGN
633. // §10.2/§10.6) recording last_operation.result=failed. The manifest write is
634. // emitted as a structured FINALIZE step (evaluator iter5 item 3).
635. func (e *Engine) dockerFinalizeFailed(ctx context.Context, sl stepLogger, t transport.Transport, s *spec.Deployment,
636. 	p layout.Paths, prev, prevImage string, started time.Time) error {
637. 	if prev == "" {
638. 		return nil
639. 	}
640. 	m := &Manifest{Schema: 1, App: s.Metadata.Name, Pattern: string(s.Pattern.Type),
641. 		CurrentVersion: prev, CurrentRelease: "docker://" + s.Pattern.ContainerName,
642. 		ProviderVersion: ProviderVersion,
643. 		Extra:           map[string]string{"image_id": prevImage},
644. 		LastOperation: LastOp{Type: "deploy", Result: "failed",
645. 			Started: started.Format(time.RFC3339), Finished: time.Now().UTC().Format(time.RFC3339)},
646. 	}
647. 	if err := sl.timed(ctx, "FINALIZE", func() error {
648. 		if derr := ensureDir(ctx, t, p.Root); derr != nil {
649. 			return derr
650. 		}
651. 		return WriteManifest(ctx, t, p, m)
652. 	}); err != nil {
653. 		e.warnf("docker failed-manifest write on %s: %v", t.Host(), err)
654. 		return err
655. 	}
656. 	return nil
657. }
