749. // preflight = global gates + pattern gates (DESIGN §10.1 step 3).
750. func (e *Engine) preflight(ctx context.Context, t transport.Transport, s *spec.Deployment,
751. 	p layout.Paths, pat pattern.Pattern, rc pattern.ReleaseCtx) error {
752. 	host := t.Host()
753. 	if t.OS() == spec.OSWindows {
754. 		script := fmt.Sprintf(`if($PSVersionTable.PSVersion.Major -lt 5){ Write-Error ("powershell " + $PSVersionTable.PSVersion + " < 5.1"); exit 1 }
755. $drive = (Split-Path -Qualifier %s) + '\'
756. $free = (Get-PSDrive -Name $drive.Substring(0,1)).Free
757. if($free -lt 500MB){ Write-Error ("free space " + [math]::Round($free/1MB) + "MB < 500MB on " + $drive); exit 1 }
758. exit 0`, psq(p.Root))
759. 		r, err := t.Exec(ctx, transport.Cmd{Shell: transport.ShellPowerShell, Script: script, TimeoutSec: 60})
760. 		if err != nil {
761. 			return wrapTransportErr(err, host, "PREFLIGHT")
762. 		}
763. 		if r.ExitCode != 0 {
764. 			return coded("ERR_PREFLIGHT", host, "PREFLIGHT", fmt.Errorf("%s", strings.TrimSpace(r.Stderr+r.Stdout)))
765. 		}
766. 	} else {
767. 		script := fmt.Sprintf(`command -v unzip >/dev/null || { echo 'unzip missing' >&2; exit 1; }
768. command -v curl >/dev/null || { echo 'curl missing' >&2; exit 1; }
769. mkdir -p %s 2>/dev/null || true
770. avail=$(df -Pm "$(dirname %s)" | awk 'NR==2{print $4}')
771. [ "$avail" -ge 500 ] || { echo "free space ${avail}MB < 500MB" >&2; exit 1; }`, shq(p.Root), shq(p.Root))
772. 		r, err := t.Exec(ctx, transport.Cmd{Shell: transport.ShellSh, Script: script, TimeoutSec: 60})
773. 		if err != nil {
774. 			return wrapTransportErr(err, host, "PREFLIGHT")
775. 		}
776. 		if r.ExitCode != 0 {
777. 			return coded("ERR_PREFLIGHT", host, "PREFLIGHT", fmt.Errorf("%s", strings.TrimSpace(r.Stderr+r.Stdout)))
778. 		}
779. 	}
780. 	// DESIGN §11: lab-insecure transport settings are permitted but MUST emit
781. 	// exactly one WARN diag per apply — see warnInsecureTransport (dedups across
782. 	// the cluster path's per-host preflights).
783. 	e.warnInsecureTransport(s)
784. 	if err := pat.Preflight(ctx, t, rc); err != nil {
785. 		return err
786. 	}
787. 	return nil
788. }
789. 
790. // stageOnHost = FETCH+CHECKSUM+EXTRACT+deps+RENDER into the immutable release
791. // dir. Cached releases (marker sha match) skip fetch/extract (DESIGN §10.5).
792. // Every fixed step is logged through sl in execution order; conditional steps
793. // (FETCH/CHECKSUM/EXTRACT) are simply not entered when the release is cached, so
794. // they never appear in the log (DESIGN §10.5 / test "conditional steps").
795. func (e *Engine) stageOnHost(ctx context.Context, sl stepLogger, t transport.Transport, s *spec.Deployment,
796. 	p layout.Paths, pat pattern.Pattern, rc pattern.ReleaseCtx) (err error) {
797. 	host := t.Host()
798. 	sl = sl.forHost(host)
799. 	stageStart := time.Now()
800. 	if err := ensureLayout(ctx, t, p); err != nil {
801. 		sl.emit(ctx, "STAGE", stageStart)
802. 		return coded("ERR_CONNECT", host, "STAGE", err)
803. 	}
804. 	// STAGING WIPE (start): staging/ is scratch, wiped whole at the start of
805. 	// EVERY op — cached or not (DESIGN §9.1 "wiped at start & end of every op").
806. 	if err := e.wipeStaging(ctx, t, p); err != nil {
807. 		sl.emit(ctx, "STAGE", stageStart)
808. 		return coded("ERR_CONNECT", host, "STAGE", err)
809. 	}
810. 	// NOTE: staging-dir prep (ensureLayout + wipe) runs first physically, but the
811. 	// canonical step order (implementation-plan.md:224 / DESIGN §8.5) is
812. 	// FETCH → CHECKSUM → STAGE → EXTRACT. The STAGE record is therefore emitted
813. 	// AFTER fetch+verify below (the verified package is what gets "staged" for
814. 	// extraction), so the emitted trace matches the pinned fixed-step order.
815. 	// STAGING WIPE (end): declared FIRST so it runs LAST (LIFO) — after the
816. 	// incomplete-release cleanup below has settled `err`. A cleanup failure is
817. 	// surfaced as the op error when the op otherwise succeeded (never leave a
818. 	// dirty staging silently); when the op already failed we warn so the root
819. 	// cause is preserved.
820. 	defer func() {
821. 		if werr := e.wipeStaging(ctx, t, p); werr != nil {
822. 			if err == nil {
823. 				err = coded("ERR_CONNECT", host, "STAGE", fmt.Errorf("staging cleanup: %w", werr))
824. 			} else {
825. 				e.warnf("staging cleanup failed on %s after prior error: %v", host, werr)
826. 			}
827. 		}
828. 	}()
829. 	// INCOMPLETE-RELEASE CLEANUP: declared SECOND so it runs FIRST (before the
830. 	// staging wipe), while `err` still reflects the genuine operation result.
831. 	// Any pre-switch failure (fetch/extract/deps/marker/render/post_install)
832. 	// after THIS op created the release removes the partial release so only a
833. 	// staging-only failure state remains (DESIGN §10.2). A cached release we did
834. 	// NOT create survives a render/post_install error. Cleanup failures are
835. 	// joined onto the op error so they cannot masquerade as a clean failure.
836. 	createdRelease := false
837. 	defer func() {
838. 		if err != nil && createdRelease {
839. 			err = e.cleanupIncompleteRelease(ctx, t, p, host, err)
840. 		}
841. 	}()
842. 	cached, cerr := e.releaseCached(ctx, t, p, s.Artifact.Version, s.Artifact.Checksum)
843. 	if cerr != nil {
844. 		return coded("ERR_CONNECT", host, "STAGE", cerr)
845. 	}
846. 	if !cached {
847. 		fetchStart := time.Now()
848. 		ferr := e.fetchToStaging(ctx, t, s, p)
849. 		// FETCH covers the download; CHECKSUM covers artifact verification. Both
850. 		// are emitted even on failure so the step trace always records where
851. 		// staging stopped. A checksum-mismatch is surfaced by fetchToStaging as a
852. 		// CodedError(ERR_CHECKSUM_MISMATCH): the download reached the verify
853. 		// stage, so FETCH is recorded as done and CHECKSUM is recorded as the
854. 		// failing step.
855. 		sl.emit(ctx, "FETCH", fetchStart)
856. 		if isChecksumErr(ferr) {
857. 			sl.emit(ctx, "CHECKSUM", time.Now())
858. 			return ferr
859. 		}
860. 		if ferr != nil {
861. 			return ferr // fetch writes only to staging; release tree untouched
862. 		}
863. 		sl.emit(ctx, "CHECKSUM", time.Now())
864. 		// STAGE: the verified package is now staged, ready for extraction.
865. 		sl.emit(ctx, "STAGE", stageStart)
866. 		// extract creates the release dir — from here the release is "ours" and
867. 		// every failure below trips the incomplete-release cleanup defer.
868. 		createdRelease = true
869. 		if xerr := sl.timed(ctx, "EXTRACT", func() error { return e.extract(ctx, t, p) }); xerr != nil {
870. 			return xerr
871. 		}
872. 		if merr := e.writeReleaseMarker(ctx, t, p, s); merr != nil {
873. 			return coded("ERR_CONNECT", host, "STAGE", merr)
874. 		}
875. 	} else {
876. 		// Cached release: FETCH/CHECKSUM/EXTRACT are skipped (conditional steps),
877. 		// but STAGE still records that the cached package is staged for this op.
878. 		sl.emit(ctx, "STAGE", stageStart)
879. 		tflog.Info(ctx, "release cached; skipping fetch/extract",
880. 			map[string]interface{}{"host": host, "version": s.Artifact.Version})
881. 	}
882. 	// node_web_app dependency install (`npm ci --omit=dev`) runs for BOTH freshly
883. 	// extracted AND cached releases (DESIGN §9.4). A cached release previously
884. 	// deployed with install_deps=false must still get its deps installed (and its
885. 	// package-lock.json validated) when this apply flips install_deps=true — so
886. 	// InstallDeps cannot live only on the fresh-extract path. It no-ops for other
887. 	// patterns and when install_deps=false. On a freshly-created release a failure
888. 	// trips the incomplete-release cleanup (createdRelease=true); on a cached
889. 	// release we did not create the tree survives for inspection.
890. 	if n, ok := pat.(*pattern.NodeWebApp); ok {
891. 		if derr := n.InstallDeps(ctx, t, rc); derr != nil {
892. 			return derr
893. 		}
894. 	}
895. 	// RENDER: files land in the release dir every apply (DESIGN §6.4). A failure
896. 	// here on a freshly-created release trips the incomplete-release cleanup.
897. 	renderStart := time.Now()
898. 	for _, f := range s.Files {
899. 		var dest string
900. 		if t.OS() == spec.OSWindows {
901. 			dest = p.Release + `\` + strings.ReplaceAll(strings.TrimLeft(f.Path, `\/`), "/", `\`)
902. 		} else {
903. 			dest = p.Release + "/" + strings.TrimLeft(f.Path, "/")
904. 		}
905. 		if werr := writeSmallFile(ctx, t, dest, f.Content); werr != nil {
906. 			sl.emit(ctx, "RENDER", renderStart)
907. 			return coded("ERR_EXTRACT", host, "RENDER", werr)
908. 		}
909. 	}
910. 	sl.emit(ctx, "RENDER", renderStart)
911. 	// post_install hook runs in release dir after extract, before switchover;
912. 	// non-zero exit ⇒ ERR_SERVICE_INSTALL (DESIGN §6.4). console_app is the sole
913. 	// exception: DESIGN §9.3 sequences its post_install AFTER switch in <cur>, so
914. 	// the ConsoleApp pattern owns that hook (in Configure) — running it here too
915. 	// would execute post_install twice.
916. 	if err := e.runPostInstall(ctx, t, s, p.Release, rc, host); err != nil {
917. 		return err
918. 	}
919. 	return nil
920. }
921. 
922. // runPostInstall executes the pattern's post_install hook in the given release
923. // directory (DESIGN §6.4). It is a no-op when no hook is configured or for the
924. // console_app pattern (which sequences its own hook after switchover). It is
925. // invoked both from staging (fresh/upgrade deploys) and from Reconfigure, so a
926. // configuration-only update that changes post_install actually runs the new hook
927. // rather than silently recording it in Terraform state.
928. func (e *Engine) runPostInstall(ctx context.Context, t transport.Transport, s *spec.Deployment,
929. 	releasePath string, rc pattern.ReleaseCtx, host string) error {
930. 	hook := s.Pattern.PostInstall
931. 	if hook == "" || s.Pattern.Type == spec.PatternConsoleApp {
932. 		return nil
933. 	}
934. 	var r transport.Result
935. 	var xerr error
936. 	if t.OS() == spec.OSWindows {
937. 		r, xerr = t.Exec(ctx, transport.Cmd{Shell: transport.ShellPowerShell, Env: rc.Env, TimeoutSec: 600,
938. 			Script: fmt.Sprintf("Set-Location %s\n%s\nexit $LASTEXITCODE", psq(releasePath), hook)})
939. 	} else {
940. 		r, xerr = t.Exec(ctx, transport.Cmd{Shell: transport.ShellSh, Env: rc.Env, TimeoutSec: 600,
941. 			Script: fmt.Sprintf("cd %s && %s", shq(releasePath), hook)})
942. 	}
943. 	if xerr != nil {
944. 		return wrapTransportErr(xerr, host, "STAGE")
945. 	}
946. 	if r.ExitCode != 0 {
947. 		return coded("ERR_SERVICE_INSTALL", host, "STAGE",
948. 			fmt.Errorf("post_install exit=%d: %s", r.ExitCode, strings.TrimSpace(r.Stderr+r.Stdout)))
949. 	}
950. 	return nil
951. }
952. 
953. // cleanupIncompleteRelease removes a release dir that THIS op created after a
954. // pre-switch failure (DESIGN §10.2 staging-only failure state) and JOINS any
955. // removal error onto the operation error, so a failed cleanup cannot masquerade
956. // as a clean staging-only failure.
957. func (e *Engine) cleanupIncompleteRelease(ctx context.Context, t transport.Transport, p layout.Paths, host string, opErr error) error {
958. 	if rerr := e.removePath(ctx, t, p.Release); rerr != nil {
959. 		return errors.Join(opErr, coded("ERR_CONNECT", host, "STAGE",
960. 			fmt.Errorf("incomplete-release cleanup: %w", rerr)))
961. 	}
962. 	return opErr
963. }
964. 
965. // switchOn = STOP + SWITCH + CONFIGURE + START for one host (DESIGN §10.1 7–10).
966. func (e *Engine) switchOn(ctx context.Context, sl stepLogger, t transport.Transport, s *spec.Deployment,
967. 	p layout.Paths, pat pattern.Pattern, rc pattern.ReleaseCtx) error {
968. 	sl = sl.forHost(t.Host())
969. 	rc.EmitStep = sl.emit
970. 	if err := sl.timed(ctx, "STOP", func() error { return pat.Stop(ctx, t, rc) }); err != nil {
971. 		return err
972. 	}
973. 	if err := sl.timed(ctx, "SWITCH", func() error { return e.switchJunction(ctx, t, p) }); err != nil {
974. 		return err
975. 	}
976. 	if err := sl.timed(ctx, "CONFIGURE", func() error { return pat.Configure(ctx, t, rc) }); err != nil {
977. 		return err
978. 	}
979. 	return sl.timed(ctx, "START", func() error { return pat.Start(ctx, t, rc) })
980. }
