1171. func (e *Engine) removePath(ctx context.Context, t transport.Transport, path string) error {
1172. 	if t.OS() == spec.OSWindows {
1173. 		// SilentlyContinue makes a missing path a no-op (idempotent), but a
1174. 		// real removal failure (locked/permission) leaves the path present, so
1175. 		// we re-check and exit nonzero to surface it to the caller.
1176. 		script := fmt.Sprintf(`Remove-Item -Recurse -Force -ErrorAction SilentlyContinue %s
1177. if(Test-Path %s){ Write-Error 'remove failed'; exit 1 }
1178. exit 0`, psq(path), psq(path))
1179. 		r, err := t.Exec(ctx, transport.Cmd{Shell: transport.ShellPowerShell, Script: script, TimeoutSec: 300})
1180. 		if err != nil {
1181. 			return err
1182. 		}
1183. 		if r.ExitCode != 0 {
1184. 			return fmt.Errorf("remove %s: %s", path, strings.TrimSpace(r.Stderr+r.Stdout))
1185. 		}
1186. 		return nil
1187. 	}
1188. 	// `rm -rf` is a no-op on a missing path; the `[ ! -e ]` guard turns a real
1189. 	// removal failure into a nonzero exit the caller can propagate.
1190. 	script := fmt.Sprintf("rm -rf %s\n[ ! -e %s ]", shq(path), shq(path))
1191. 	r, err := t.Exec(ctx, transport.Cmd{Shell: transport.ShellSh, Script: script, TimeoutSec: 300})
1192. 	if err != nil {
1193. 		return err
1194. 	}
1195. 	if r.ExitCode != 0 {
1196. 		return fmt.Errorf("remove %s: %s", path, strings.TrimSpace(r.Stderr+r.Stdout))
1197. 	}
1198. 	return nil
1199. }
