1212. // pruneReleases keeps newest keep_releases dirs; current+previous always
1213. // protected (DESIGN §10.1 step 13). Deletion list computed runner-side.
1214. func (e *Engine) pruneReleases(ctx context.Context, t transport.Transport, s *spec.Deployment,
1215. 	p layout.Paths, m *Manifest) error {
1216. 	keep := s.Strategy.EffectiveKeepReleases()
1217. 	var listing string
1218. 	if t.OS() == spec.OSWindows {
1219. 		r, err := t.Exec(ctx, transport.Cmd{Shell: transport.ShellPowerShell, TimeoutSec: 60,
1220. 			Script: fmt.Sprintf(`Get-ChildItem -Directory %s | ForEach-Object { $_.Name + '|' + $_.LastWriteTimeUtc.Ticks }`, psq(p.Releases))})
1221. 		if err != nil || r.ExitCode != 0 {
1222. 			return fmt.Errorf("list releases: err=%v %s", err, r.Stderr)
1223. 		}
1224. 		listing = r.Stdout
1225. 	} else {
1226. 		r, err := t.Exec(ctx, transport.Cmd{Shell: transport.ShellSh, TimeoutSec: 60,
1227. 			Script: fmt.Sprintf(`for d in %s/*/; do [ -d "$d" ] && printf '%%s|%%s\n' "$(basename "$d")" "$(stat -c %%Y "$d")"; done`, shq(p.Releases))})
1228. 		if err != nil || r.ExitCode != 0 {
1229. 			return fmt.Errorf("list releases: err=%v %s", err, r.Stderr)
1230. 		}
1231. 		listing = r.Stdout
1232. 	}
1233. 	type rel struct {
1234. 		name string
1235. 		ts   int64
1236. 	}
1237. 	var rels []rel
1238. 	for _, line := range strings.Split(listing, "\n") {
1239. 		line = strings.TrimSpace(line)
1240. 		if line == "" {
1241. 			continue
1242. 		}
1243. 		parts := strings.SplitN(line, "|", 2)
1244. 		if len(parts) != 2 {
1245. 			continue
1246. 		}
1247. 		var ts int64
1248. 		_, _ = fmt.Sscanf(parts[1], "%d", &ts)
1249. 		rels = append(rels, rel{parts[0], ts})
1250. 	}
1251. 	sort.Slice(rels, func(i, j int) bool { return rels[i].ts > rels[j].ts }) // newest first
1252. 	// keep_releases is the TOTAL retention budget (DESIGN CAP-02: keep=2 ⇒ exactly
1253. 	// 2 dirs = newest+previous). current + previous are ALWAYS retained and count
1254. 	// toward the budget; remaining slots go to the newest non-protected releases.
1255. 	protected := map[string]bool{m.CurrentVersion: true}
1256. 	if m.PreviousVersion != "" {
1257. 		protected[m.PreviousVersion] = true
1258. 	}
1259. 	protectedExisting := 0
1260. 	for _, r := range rels {
1261. 		if protected[r.name] {
1262. 			protectedExisting++
1263. 		}
1264. 	}
1265. 	slots := keep - protectedExisting // budget left for non-protected releases
1266. 	if slots < 0 {
1267. 		slots = 0 // protected (current+previous) is never deleted, even if > keep
1268. 	}
1269. 	filled := 0
1270. 	var firstErr error
1271. 	for _, r := range rels { // newest first
1272. 		if protected[r.name] {
1273. 			continue // current/previous: always retained
1274. 		}
1275. 		if filled < slots {
1276. 			filled++
1277. 			continue
1278. 		}
1279. 		if err := e.removePath(ctx, t, p.Releases+sepFor(t.OS())+r.name); err != nil && firstErr == nil {
1280. 			firstErr = fmt.Errorf("prune %s: %w", r.name, err)
1281. 		}
1282. 	}
1283. 	return firstErr
1284. }
