1365. // Reconfigure re-applies pattern configuration (a Windows service's description,
1366. // start type, recovery actions, arguments, and environment) to the CURRENTLY
1367. // deployed release and restarts it so the new settings take effect. It exists
1368. // because a configuration-only change — one that leaves artifact.version and
1369. // artifact.checksum untouched — hits Deploy's idempotency short-circuit
1370. // (DESIGN §10.1 step 2) and would otherwise never reach CONFIGURE, silently
1371. // skipping the mutable settings while Terraform records the new desired state.
1372. //
1373. // It is transactional, concurrency-safe, and rollback-safe. It acquires the SAME
1374. // per-app deploy lock BEFORE it reads the manifest (so a concurrent deploy/destroy
1375. // cannot complete between the manifest read and our mutations and leave us
1376. // configuring — and re-finalizing — a stale release), then runs STOP → CONFIGURE →
1377. // START → HEALTH so the new configuration is actually active on the running
1378. // process (not just written to disk), and only then re-finalizes the manifest.
1379. // If any step after STOP fails, it restores the PRIOR configuration (the settings
1380. // Terraform still records in state) and health-checks it, so the machine is never
1381. // left stopped or running rejected settings; the original error is surfaced so the
1382. // apply fails and state stays accurate. If restoration itself fails it persists a
1383. // failed manifest (DESIGN §10.6) and returns ERR_ROLLBACK_FAILED. Returns a nil
1384. // status with a nil error when nothing is deployed yet. Single-host.
1385. func (e *Engine) Reconfigure(ctx context.Context, s, prior *spec.Deployment) (*Status, error) {
1386. 	host := strings.ToLower(s.Target.Hosts[0])
1387. 	sl := newStepLogger(s, host)
1388. 	if prior == nil {
1389. 		prior = s
1390. 	}
1391. 	t, err := e.NewTransport(&s.Target, host)
1392. 	if err != nil {
1393. 		return nil, coded("ERR_SPEC_INVALID", host, "VALIDATE", err)
1394. 	}
1395. 	pat, verr := pattern.For(s.Pattern.Type)
1396. 	if verr != nil {
1397. 		return nil, coded("ERR_UNSUPPORTED", host, "VALIDATE", verr)
1398. 	}
1399. 	if err := t.Connect(ctx); err != nil {
1400. 		return nil, wrapTransportErr(err, host, "CONNECT")
1401. 	}
1402. 	defer t.Close()
1403. 	// The lock and manifest live at the app root (version-independent), so we can
1404. 	// build the lock paths and acquire the lock BEFORE reading the manifest.
1405. 	p := layout.NewPaths(s.Target.OS, s.Pattern.EffectiveInstallRoot(s.Target.OS), s.Metadata.Name, s.Artifact.Version)
1406. 	lstart := time.Now()
1407. 	lk, lwarn, err := AcquireLock(ctx, t, p, lockOwner(), "reconfigure", s.Strategy.EffectiveLockTimeout())
1408. 	sl.emit(ctx, "LOCK", lstart)
1409. 	if err != nil {
1410. 		return nil, err
1411. 	}
1412. 	if lwarn != "" {
1413. 		e.warnf("%s", lwarn)
1414. 	}
1415. 	defer func() {
1416. 		rctx, cancel := lockCleanupContext(ctx)
1417. 		defer cancel()
1418. 		ustart := time.Now()
1419. 		if rerr := ReleaseLock(rctx, lk); rerr != nil {
1420. 			e.warnf("lock release failed on %s: %v", host, rerr)
1421. 		}
1422. 		sl.emit(ctx, "UNLOCK", ustart)
1423. 	}()
1424. 	// Now that we hold the lock, read the manifest under it — nothing can change
1425. 	// current_version/checksum out from under us for the rest of this operation.
1426. 	m, err := ReadManifest(ctx, t, p)
1427. 	if err != nil {
1428. 		return nil, coded("ERR_CONNECT", host, "PREFLIGHT", err)
1429. 	}
1430. 	present, deployedVer, warn := ReconcileManifest(m)
1431. 	if !present {
1432. 		return nil, nil
1433. 	}
1434. 	if warn != "" {
1435. 		e.warnf("%s", warn)
1436. 	}
1437. 	// Reconfigure the CURRENT deployed version's release (mirrors ReadStatus): the
1438. 	// pattern context version MUST be the manifest's current_version so we target
1439. 	// the live binary path, not a desired version that is not yet on disk.
1440. 	rp := layout.NewPaths(s.Target.OS, s.Pattern.EffectiveInstallRoot(s.Target.OS), s.Metadata.Name, m.CurrentVersion)
1441. 	newRC := releaseCtxVersion(s, rp, m.CurrentVersion)
1442. 	newRC.EmitStep = sl.emit
1443. 	// Pattern preflight MUST run before any mutation (DESIGN §8.1): a same-artifact
1444. 	// change to node_exe, or a launcher=exe→dotnet_dll switch, must validate the new
1445. 	// tooling (node --version / dotnet --list-runtimes contains Microsoft.AspNetCore.App)
1446. 	// BEFORE we stop and reconfigure the running service — otherwise the service could
1447. 	// be torn down and re-registered against a launcher the target cannot run.
1448. 	if err := sl.timed(ctx, "PREFLIGHT", func() error { return e.preflight(ctx, t, s, rp, pat, newRC) }); err != nil {
1449. 		return nil, err
1450. 	}
1451. 	started := time.Now().UTC()
1452. 	writeManifest := func(result string) *Manifest {
1453. 		return &Manifest{
1454. 			Schema: 1, App: s.Metadata.Name, Pattern: string(s.Pattern.Type),
1455. 			CurrentVersion: m.CurrentVersion, PreviousVersion: m.PreviousVersion,
1456. 			CurrentRelease: rp.Release, ArtifactChecksum: m.ArtifactChecksum,
1457. 			ProviderVersion: ProviderVersion,
1458. 			LastOperation: LastOp{Type: "reconfigure", Result: result,
1459. 				Started: started.Format(time.RFC3339), Finished: time.Now().UTC().Format(time.RFC3339)},
1460. 		}
1461. 	}
1462. 	// activate follows DESIGN §10.2: STOP → CONFIGURE → START → HEALTH for a given
1463. 	// release context and health check. It is used both to apply the new settings
1464. 	// and to RESTORE the prior ones — the restore path MUST stop the service that is
1465. 	// running the rejected configuration before re-applying the prior settings, or
1466. 	// the prior environment/arguments would be written but never activated. The
1467. 	// health check is passed in so the restored configuration is validated against
1468. 	// the PRIOR health check, not the new one.
1469. 	//
1470. 	// preStart, when non-nil, runs at the pre-activation point (after CONFIGURE,
1471. 	// before START). Only the forward path supplies it, and only to run a CHANGED
1472. 	// post_install hook — the restore path passes nil so the PRIOR hook is never
1473. 	// re-executed while rolling back.
1474. 	activate := func(rc pattern.ReleaseCtx, hc *spec.HealthCheck, preStart func() error) error {
1475. 		// STOP and CONFIGURE return the pattern error UNWRAPPED — exactly as the
1476. 		// Deploy path (switchOn) and the START/HEALTH steps below already do.
1477. 		// pat.Stop / pat.Configure yield a correctly-coded *pattern.StepError:
1478. 		// ERR_SERVICE_STOP / ERR_SERVICE_INSTALL for a remote exit-code failure, but
1479. 		// ERR_CONNECT when the transport drops mid-step. Re-coding them here with a
1480. 		// blanket coded(...) would override that ERR_CONNECT — diverging from the
1481. 		// DESIGN §12 taxonomy (a stable contract for pipelines & tests) and from the
1482. 		// Deploy path, where the identical failure keeps its original code — and would
1483. 		// double the "[ERR_SERVICE_STOP] [ERR_SERVICE_STOP]" prefix on a genuine
1484. 		// service failure.
1485. 		if err := sl.timed(ctx, "STOP", func() error { return pat.Stop(ctx, t, rc) }); err != nil {
1486. 			return err
1487. 		}
1488. 		if err := sl.timed(ctx, "CONFIGURE", func() error { return pat.Configure(ctx, t, rc) }); err != nil {
1489. 			return err
1490. 		}
1491. 		if preStart != nil {
1492. 			if err := preStart(); err != nil {
1493. 				return err
1494. 			}
1495. 		}
1496. 		if err := sl.timed(ctx, "START", func() error { return pat.Start(ctx, t, rc) }); err != nil {
1497. 			return err
1498. 		}
1499. 		return sl.timed(ctx, "HEALTH", func() error {
1500. 			return RunHealthCheck(ctx, t, hc, rp.Current, rc.Env)
1501. 		})
1502. 	}
1503. 	// forward applies the NEW configuration AND finalizes it. FINALIZE and the
1504. 	// post-finalize Status read are part of the transaction: if either fails the
1505. 	// machine must not be left on the new configuration while Terraform retains the
1506. 	// prior state, so their failure triggers the same rollback as a health failure.
1507. 	var (
1508. 		okManifest *Manifest
1509. 		okStatus   string
1510. 	)
1511. 	// node is non-nil for node_web_app; depsBackedUp tracks whether we snapshotted
1512. 	// node_modules before `npm ci` so the rollback path can restore it.
1513. 	node, _ := pat.(*pattern.NodeWebApp)
1514. 	depsBackedUp := false
1515. 	forward := func() error {
1516. 		// Run post_install ONLY when the hook actually CHANGED for this same-artifact
1517. 		// reconfigure, at the pre-activation point (after CONFIGURE, before START) so
1518. 		// it runs before the new configuration is activated — matching its
1519. 		// after-extract/before-switchover semantics on deploy. An UNCHANGED hook is
1520. 		// not re-executed (its effect already landed when the artifact was staged),
1521. 		// and because only the forward path supplies preStart the PRIOR hook is never
1522. 		// re-run while rolling back.
1523. 		// preStart runs at the pre-activation point (after STOP+CONFIGURE, before
1524. 		// START) so the service is stopped (no locked node_modules) yet started with
1525. 		// the new dependencies/hook in place. Two things happen here, in deploy order:
1526. 		//   1. node_web_app InstallDeps (`npm ci --omit=dev`) — self-gates on
1527. 		//      install_deps, so a same-artifact install_deps=false→true toggle actually
1528. 		//      installs deps (and validates package-lock.json) instead of no-op'ing.
1529. 		//   2. a CHANGED post_install hook — an UNCHANGED hook is not re-executed (its
1530. 		//      effect already landed at stage time). Only the forward path supplies
1531. 		//      preStart, so neither re-runs while rolling back.
1532. 		_, isNode := pat.(*pattern.NodeWebApp)
1533. 		postInstallChanged := s.Pattern.PostInstall != prior.Pattern.PostInstall
1534. 		var preStart func() error
1535. 		if isNode || postInstallChanged {
1536. 			preStart = func() error {
1537. 				if node != nil {
1538. 					// Snapshot node_modules BEFORE npm ci so a partial install can be
1539. 					// rolled back to a runnable tree (self-gates on install_deps).
1540. 					if s.Pattern.InstallDeps {
1541. 						if berr := sl.timed(ctx, "STAGE", func() error { return node.BackupDeps(ctx, t, newRC) }); berr != nil {
1542. 							return berr
1543. 						}
1544. 						depsBackedUp = true
1545. 					}
1546. 					if derr := sl.timed(ctx, "STAGE", func() error { return node.InstallDeps(ctx, t, newRC) }); derr != nil {
1547. 						return derr
1548. 					}
1549. 				}
1550. 				if postInstallChanged {
1551. 					return e.runPostInstall(ctx, t, s, rp.Release, newRC, host)
1552. 				}
1553. 				return nil
1554. 			}
1555. 		}
1556. 		if err := activate(newRC, &s.HealthCheck, preStart); err != nil {
1557. 			return err
1558. 		}
1559. 		nm := writeManifest("success")
1560. 		if err := sl.timed(ctx, "FINALIZE", func() error { return WriteManifest(ctx, t, rp, nm) }); err != nil {
1561. 			return coded("ERR_CONNECT", host, "FINALIZE", err)
1562. 		}
1563. 		st, serr := pat.Status(ctx, t, newRC)
1564. 		if serr != nil {
1565. 			return wrapTransportErr(serr, host, "READ")
1566. 		}
1567. 		okManifest, okStatus = nm, st
1568. 		return nil
1569. 	}
1570. 	if ferr := forward(); ferr != nil {
1571. 		// Rollback (DESIGN §10.2 restore): restore the PRIOR configuration — the
1572. 		// settings Terraform still holds in state — validated against the PRIOR
1573. 		// health check, so the machine is not left stopped or running rejected
1574. 		// settings.
1575. 		priorRC := releaseCtxVersion(prior, rp, m.CurrentVersion)
1576. 		priorRC.EmitStep = sl.emit
1577. 		rbStart := time.Now()
1578. 		// A partial `npm ci` may have left the ACTIVE release without a runnable
1579. 		// dependency tree — restore the node_modules snapshot BEFORE restoring the
1580. 		// prior service configuration, so the prior app comes up against its
1581. 		// original dependencies. If the snapshot restore ITSELF fails, the prior
1582. 		// dependency tree is UNRECOVERABLE: do NOT attempt to start the prior
1583. 		// configuration (it would come up against a broken/absent node_modules and
1584. 		// could still report healthy under health_check=none) — escalate straight
1585. 		// to ERR_ROLLBACK_FAILED so the operator is forced to repair.
1586. 		var rerr error
1587. 		if depsBackedUp {
1588. 			rerr = node.RestoreDeps(ctx, t, newRC)
1589. 		}
1590. 		if rerr == nil {
1591. 			rerr = activate(priorRC, &prior.HealthCheck, nil)
1592. 		}
1593. 		if rerr == nil {
1594. 			// Prior configuration restored and healthy — re-finalize the manifest to
1595. 			// record the rolled-back reconfigure (version/checksum unchanged).
1596. 			rbm := writeManifest("rolled_back")
1597. 			rerr = sl.timed(ctx, "FINALIZE", func() error { return WriteManifest(ctx, t, rp, rbm) })
1598. 		}
1599. 		sl.emit(ctx, "ROLLBACK", rbStart)
1600. 		if rerr != nil {
1601. 			// DESIGN §10.6: restoration (or its manifest write) failed — persist the
1602. 			// required deploy/failed marker and SURFACE a persistence failure so the
1603. 			// operator is forced to repair, rather than only warning. finalizeFailed
1604. 			// writes last_operation.type=deploy, result=failed.
1605. 			detail := fmt.Errorf("MACHINE IN UNKNOWN STATE host=%s: reconfigure failed and restore of prior configuration failed; reconfigure error: %v; restore error: %v",
1606. 				host, ferr, rerr)
1607. 			if fmErr := e.finalizeFailed(ctx, sl, t, s, rp, m.CurrentVersion, started, "failed"); fmErr != nil {
1608. 				detail = fmt.Errorf("%v; failed-marker persistence ALSO failed (manual repair required): %v", detail, fmErr)
1609. 			}
1610. 			return nil, coded("ERR_ROLLBACK_FAILED", host, "ROLLBACK", detail)
1611. 		}
1612. 		// Surface the original error so the apply fails and Terraform retains the
1613. 		// (now accurate) prior state.
1614. 		return nil, fmt.Errorf("%w; prior configuration restored (healthy)", ferr)
1615. 	}
1616. 	// Reconfigure succeeded end-to-end: discard the node_modules snapshot (the new
1617. 	// dependency tree is live and healthy). Cleanup is best-effort — a leftover
1618. 	// backup dir wastes disk but does not affect correctness.
1619. 	if depsBackedUp {
1620. 		if cerr := node.CommitDeps(ctx, t, newRC); cerr != nil {
1621. 			e.warnf("node_modules backup cleanup failed on %s: %v", host, cerr)
1622. 		}
1623. 	}
1624. 	out := statusFrom(okManifest, host, okStatus)
1625. 	out.DeployedVersion = deployedVer
1626. 	return out, nil
1627. }
1628. 
1629. // Destroy honors destroy_mode purge|unregister|abandon (DESIGN §10.6).
1630. func (e *Engine) Destroy(ctx context.Context, s *spec.Deployment, mode string) error {
1631. 	if mode == "abandon" {
1632. 		return nil
1633. 	}
1634. 	if s.Pattern.Type == spec.PatternClusterGeneric {
1635. 		return e.destroyCluster(ctx, s, mode)
1636. 	}
1637. 	host := strings.ToLower(s.Target.Hosts[0])
1638. 	t, err := e.NewTransport(&s.Target, host)
1639. 	if err != nil {
1640. 		return err
1641. 	}
1642. 	if err := t.Connect(ctx); err != nil {
1643. 		return wrapTransportErr(err, host, "CONNECT")
1644. 	}
1645. 	defer t.Close()
1646. 	p := layout.NewPaths(s.Target.OS, s.Pattern.EffectiveInstallRoot(s.Target.OS), s.Metadata.Name, s.Artifact.Version)
1647. 	pat, err := pattern.For(s.Pattern.Type)
1648. 	if err != nil {
1649. 		return err
1650. 	}
1651. 	lk, warn, err := AcquireLock(ctx, t, p, lockOwner(), "destroy", s.Strategy.EffectiveLockTimeout())
1652. 	if err != nil {
1653. 		return err
1654. 	}
1655. 	if warn != "" {
1656. 		e.warnf("%s", warn)
1657. 	}
1658. 	// Release the lock on EVERY post-lock return path — including a failed tree
1659. 	// removal in purge mode, which previously left .lock behind (evaluator
1660. 	// item 2). The detached cleanup context ensures release runs even if ctx is
1661. 	// already canceled (item 3); release is ownership-safe (compare-and-delete).
1662. 	defer func() {
1663. 		rctx, cancel := lockCleanupContext(ctx)
1664. 		defer cancel()
1665. 		if rerr := ReleaseLock(rctx, lk); rerr != nil {
1666. 			e.warnf("lock release failed on %s: %v", host, rerr)
1667. 		}
1668. 	}()
1669. 	rc := releaseCtx(s, p)
1670. 	// Uninstall calls Stop internally, which may escalate to FORCE_KILL; wire the
1671. 	// step sink so that escalation emits a structured FORCE_KILL record on the
1672. 	// destroy path too (DESIGN §9.2 S2 / WSV-07), not only on deploy/rollback.
1673. 	rc.EmitStep = newStepLogger(s, host).emit
1674. 	if err := pat.Uninstall(ctx, t, rc, mode == "purge"); err != nil {
1675. 		return err
1676. 	}
1677. 	if mode == "purge" {
1678. 		return e.removePath(ctx, t, p.Root) // lock file goes with the tree
1679. 	}
1680. 	// unregister: keep releases/shared, drop manifest so Read sees absent.
1681. 	if err := e.removePath(ctx, t, p.Manifest); err != nil {
1682. 		return err
1683. 	}
1684. 	return nil
1685. }
