1. package pattern
2. 
3. import (
4. 	"context"
5. 	"errors"
6. 	"strings"
7. 	"testing"
8. 
9. 	"github.com/smartpcr/terraform-provider-labdeploy/internal/layout"
10. 	"github.com/smartpcr/terraform-provider-labdeploy/internal/spec"
11. 	"github.com/smartpcr/terraform-provider-labdeploy/internal/transport"
12. )
13. 
14. // dockerRC builds a docker_container ReleaseCtx exactly the way engine.releaseCtx
15. // does: builtin env merged UNDER the spec environment (DESIGN §9.1). The docker
16. // D-step scripts (§9.6) are rendered from this context.
17. func dockerRC(osKind spec.OSKind, pat spec.Pattern, src spec.Source, env map[string]string) ReleaseCtx {
18. 	root := "/opt/deploy"
19. 	if osKind == spec.OSWindows {
20. 		root = `C:\deploy`
21. 	}
22. 	p := layout.NewPaths(osKind, root, "sample-svc", "2.0.0")
23. 	s := &spec.Deployment{
24. 		Metadata:    spec.Metadata{Name: "sample-svc"},
25. 		Target:      spec.Target{OS: osKind},
26. 		Artifact:    spec.Artifact{Type: spec.ArtifactDocker, Version: "2.0.0", Source: src},
27. 		Pattern:     pat,
28. 		Environment: env,
29. 	}
30. 	merged := layout.MergeEnv(layout.BuiltinEnv(s.Metadata.Name, s.Artifact.Version, p, 0), s.Environment)
31. 	return ReleaseCtx{App: s.Metadata.Name, Version: s.Artifact.Version, P: p, Spec: s, Env: merged}
32. }
33. 
34. // dockerPattern is the reusable container spec (ports/env/volumes/restart) the
35. // golden scenarios exercise; run_args carries an extra runtime flag.
36. func dockerPattern() spec.Pattern {
37. 	return spec.Pattern{
38. 		Type:          spec.PatternDockerCont,
39. 		ContainerName: "sample",
40. 		Ports:         []string{"8080:8080", "9090:9090"},
41. 		Volumes:       []string{"/srv/data:/data"},
42. 		RestartPolicy: "always",
43. 		RunArgs:       []string{"--pull=never"},
44. 	}
45. }
46. 
47. // Scenario: Docker run script golden (DESIGN §9.6 D1..D7). Given a docker_container
48. // spec, when the D-step scripts are generated, they must match the committed
49. // goldens — including the login (D1) → tag pull (D2) → logout (D7) FETCH script
50. // and the rm -f (D4) → run (D5) START script with ports/env/volumes/restart.
51. func TestDockerRunScriptGoldenLinux(t *testing.T) {
52. 	t.Setenv("LD_REG_PW_ENV", "s3cr3t")
53. 	var d DockerContainer
54. 	rc := dockerRC(spec.OSLinux, dockerPattern(), spec.Source{
55. 		Type:  "docker_registry",
56. 		Image: "registry.example.com/app",
57. 		Tag:   "2.0.0",
58. 		Auth:  spec.SourceAuth{Username: "svc", PasswordEnv: "LD_REG_PW_ENV"},
59. 	}, map[string]string{"ASPNETCORE_ENVIRONMENT": "Production"})
60. 
61. 	// FETCH = D1 (login) + D2 (pull) + D7 (logout).
62. 	fp := &scriptTransport{osKind: spec.OSLinux}
63. 	if err := d.Pull(context.Background(), fp, rc); err != nil {
64. 		t.Fatalf("Pull: %v", err)
65. 	}
66. 	if len(fp.scripts) != 1 {
67. 		t.Fatalf("Pull should emit a single FETCH script, got %d", len(fp.scripts))
68. 	}
69. 	checkGolden(t, "docker_pull_linux.golden", fp.scripts[0])
70. 	// D1 login uses --password-stdin (credential never on the command line), and
71. 	// D7 logout must run because D1 ran.
72. 	if !strings.Contains(fp.scripts[0], "docker login registry.example.com -u 'svc' --password-stdin") {
73. 		t.Errorf("FETCH must perform D1 login via --password-stdin:\n%s", fp.scripts[0])
74. 	}
75. 	if !strings.Contains(fp.scripts[0], "docker logout registry.example.com") {
76. 		t.Errorf("FETCH must perform D7 logout because D1 login ran:\n%s", fp.scripts[0])
77. 	}
78. 	if !strings.Contains(fp.scripts[0], "docker pull 'registry.example.com/app:2.0.0'") {
79. 		t.Errorf("FETCH must perform D2 tag pull:\n%s", fp.scripts[0])
80. 	}
81. 
82. 	// START = D4 (rm -f, ignore not-found) + D5 (run with ports/env/volumes/restart).
83. 	fr := &scriptTransport{osKind: spec.OSLinux}
84. 	if err := d.Start(context.Background(), fr, rc); err != nil {
85. 		t.Fatalf("Start: %v", err)
86. 	}
87. 	if len(fr.scripts) != 1 {
88. 		t.Fatalf("Start should emit a single START script, got %d", len(fr.scripts))
89. 	}
90. 	checkGolden(t, "docker_run_linux.golden", fr.scripts[0])
91. 	if !strings.Contains(fr.scripts[0], "docker rm -f 'sample'") {
92. 		t.Errorf("START must perform D4 rm -f:\n%s", fr.scripts[0])
93. 	}
94. 	for _, want := range []string{
95. 		"--restart always",
96. 		"-p '8080:8080'", "-p '9090:9090'",
97. 		"-v '/srv/data:/data'",
98. 		`-e 'ASPNETCORE_ENVIRONMENT=Production'`,
99. 		"--pull=never",
100. 		"'registry.example.com/app:2.0.0'",
101. 	} {
102. 		if !strings.Contains(fr.scripts[0], want) {
103. 			t.Errorf("START (D5) missing %q:\n%s", want, fr.scripts[0])
104. 		}
105. 	}
106. }
107. 
108. // Scenario: Docker digest pull golden (DESIGN §6.3/§9.6 D2). A source with a
109. // digest must pull by <image>@<digest>, NOT by tag, and with no auth configured
110. // no login/logout is emitted.
111. func TestDockerPullDigestGolden(t *testing.T) {
112. 	var d DockerContainer
113. 	rc := dockerRC(spec.OSLinux, dockerPattern(), spec.Source{
114. 		Type:   "docker_registry",
115. 		Image:  "registry.example.com/app",
116. 		Digest: "sha256:deadbeefdeadbeefdeadbeefdeadbeefdeadbeefdeadbeefdeadbeefdeadbeef",
117. 	}, nil)
118. 
119. 	fp := &scriptTransport{osKind: spec.OSLinux}
120. 	if err := d.Pull(context.Background(), fp, rc); err != nil {
121. 		t.Fatalf("Pull: %v", err)
122. 	}
123. 	checkGolden(t, "docker_pull_digest.golden", fp.scripts[0])
124. 	if !strings.Contains(fp.scripts[0], "docker pull 'registry.example.com/app@sha256:deadbeef") {
125. 		t.Errorf("digest pull must reference <image>@<digest>:\n%s", fp.scripts[0])
126. 	}
127. 	if strings.Contains(fp.scripts[0], "docker login") || strings.Contains(fp.scripts[0], "docker logout") {
128. 		t.Errorf("no auth ⇒ no login/logout:\n%s", fp.scripts[0])
129. 	}
130. }
131. 
132. // Scenario: Docker rollback run golden (DESIGN §9.6 D6). Rollback re-runs D4+D5
133. // against the RECORDED old image id (not the new ref), restoring the previous
134. // container.
135. func TestDockerRollbackRunGolden(t *testing.T) {
136. 	var d DockerContainer
137. 	rc := dockerRC(spec.OSLinux, dockerPattern(), spec.Source{
138. 		Type:  "docker_registry",
139. 		Image: "registry.example.com/app",
