13. // dockerNode embeds a fakeHost and answers the §9.6 docker D-step scripts
14. // (pull/inspect/run/stop) against a tiny in-memory container state; all other
15. // scripts (connect/preflight/lock/manifest) delegate to the embedded fake.
16. type dockerNode struct {
17. 	*fakeHost
18. 	image         string   // current container image id ("" ⇒ container absent)
