309. // TestDockerSameVersionConfigChangeRedeploys covers evaluator iter3 item 3: a
310. // same-version change to the container configuration (here: ports) must NOT be a
311. // silent no-op. Idempotency is keyed off ConfigFingerprint, so an identical spec
312. // re-applies as a no-op while a changed spec triggers a fresh docker run.
313. func TestDockerSameVersionConfigChangeRedeploys(t *testing.T) {
314. 	n := &dockerNode{fakeHost: newFakeHost("lab-01"), image: "", runImage: "sha256:img"}
315. 	eng := New()
316. 	eng.NewTransport = func(tg *spec.Target, host string) (transport.Transport, error) { return n, nil }
