320. 		t.Fatalf("phase-1 deploy should succeed: %v", err)
321. 	}
322. 	afterFirst := len(n.runScripts)
323. 	if afterFirst == 0 {
324. 		t.Fatalf("phase-1 must have run the container")
325. 	}
326. 
327. 	// Phase 2: identical spec ⇒ true no-op (same version, same fingerprint, running).
328. 	if _, err := eng.Deploy(context.Background(), dockerSpecPorts(t, "2.0.0", "8080:8080")); err != nil {
329. 		t.Fatalf("phase-2 identical re-apply should succeed: %v", err)
330. 	}
331. 	if len(n.runScripts) != afterFirst {
332. 		t.Fatalf("identical same-version re-apply must be a no-op (no new docker run); runs %d→%d", afterFirst, len(n.runScripts))
333. 	}
334. 
335. 	// Phase 3: same version but a CHANGED port ⇒ different fingerprint ⇒ redeploy.
336. 	if _, err := eng.Deploy(context.Background(), dockerSpecPorts(t, "2.0.0", "8080:8080", "9090:9090")); err != nil {
337. 		t.Fatalf("phase-3 config-change re-apply should succeed: %v", err)
338. 	}
339. 	if len(n.runScripts) <= afterFirst {
340. 		t.Fatalf("a same-version CONFIG change must redeploy (new docker run), but runs stayed %d", len(n.runScripts))
341. 	}
342. }
