491. 	sl = sl.forHost(host)
492. 	started := time.Now().UTC()
493. 	if m != nil && m.CurrentVersion == s.Artifact.Version && m.Extra["config_hash"] == dc.ConfigFingerprint(rc) {
494. 		// True no-op only when the version AND the mutable container configuration
495. 		// (image ref/ports/env/volumes/restart/run_args) are unchanged AND running
496. 		// (DESIGN §10.1). A same-version config change has a different fingerprint
497. 		// and falls through to a redeploy instead of being silently ignored.
498. 		if st, err := dc.Status(ctx, t, rc); err == nil && st == "running" {
499. 			return statusFrom(m, host, st), nil
500. 		}
501. 	}
502. 	prev, oldImage := "", ""
503. 	if m != nil {
504. 		prev = m.CurrentVersion
505. 		oldImage = m.Extra["image_id"]
506. 	}
507. 	// Best-effort log/event collection on every exit path from here (including
508. 	// image-pull failure) — DESIGN §6.5. No-op when nothing is configured.
509. 	defer e.collectDeploymentLogs(ctx, t, s, p, started)
510. 	fetchStart := time.Now()
511. 	perr := dc.Pull(ctx, t, rc)
512. 	sl.emit(ctx, "FETCH", fetchStart)
513. 	if perr != nil {
514. 		return nil, perr
515. 	}
516. 	// D3 (pre-run inspect): record the live image id as the rollback anchor. A
517. 	// TRANSPORT error here must abort BEFORE D4 `rm -f` — destroying the running
518. 	// container with no recorded rollback image would leave the target
519. 	// unrecoverable (evaluator iter3 item 1). An absent container is reported as
520. 	// ("", nil) by CurrentImageID, so only a real failure surfaces an error.
521. 	cur, cerr := dc.CurrentImageID(ctx, t, rc)
522. 	if cerr != nil {
523. 		return nil, cerr
524. 	}
525. 	if cur != "" {
526. 		oldImage = cur
527. 	}
528. 	runErr := sl.timed(ctx, "START", func() error { return dc.Start(ctx, t, rc) }) // rm -f old + run new
529. 	if runErr == nil {
530. 		runErr = sl.timed(ctx, "HEALTH", func() error {
531. 			return RunHealthCheck(ctx, t, &s.HealthCheck, p.Root, rc.Env)
532. 		})
533. 	}
534. 	if runErr != nil {
535. 		if !s.Strategy.EffectiveRollback() || oldImage == "" {
536. 			// §10.2: record last_operation=failed so Read reports drift even when no
537. 			// rollback is performed (rollback disabled or previous image unknown).
538. 			// Record at the previous version if known, else the attempted version so
539. 			// a fresh docker failure still persists failed state (evaluator iter5 item 2).
540. 			failVer := prev
541. 			if failVer == "" {
542. 				failVer = s.Artifact.Version
543. 			}
544. 			fmErr := e.dockerFinalizeFailed(ctx, sl, t, s, p, failVer, oldImage, started)
545. 			out := fmt.Errorf("%w; no docker rollback performed (prev image unknown or rollback disabled)", runErr)
546. 			if fmErr != nil {
547. 				return nil, coded("ERR_CONNECT", host, "FINALIZE",
548. 					fmt.Errorf("%v; failed-manifest write error: %v", out, fmErr))
549. 			}
550. 			return nil, out
551. 		}
552. 		rbStart := time.Now()
553. 		// §9.6 D6 / §10.4: restore the PREVIOUS release. The restored container must
554. 		// advertise the previous version, so rebuild the pattern context at `prev`
555. 		// (LD_VERSION and the -e env baked into `docker run` reflect the running
556. 		// release) rather than reusing the failed new-version rc. Health is rechecked
557. 		// with the same previous-version env.
558. 		rbRC := rc
559. 		if prev != "" {
560. 			rbRC = releaseCtxVersion(s, p, prev)
561. 		}
562. 		rerr := dc.RunNew(ctx, t, rbRC, oldImage)
563. 		if rerr == nil {
564. 			rerr = RunHealthCheck(ctx, t, &s.HealthCheck, p.Root, rbRC.Env)
565. 		}
566. 		sl.emit(ctx, "ROLLBACK", rbStart)
567. 		if rerr != nil {
568. 			// §10.6: persist a failed manifest before surfacing ERR_ROLLBACK_FAILED.
569. 			// When the old container exists but no prior manifest does (prev==""),
570. 			// record at the attempted version so the failed state is still persisted
571. 			// (evaluator iter6 item 2).
572. 			failVer := prev
573. 			if failVer == "" {
574. 				failVer = s.Artifact.Version
575. 			}
576. 			fmErr := e.dockerFinalizeFailed(ctx, sl, t, s, p, failVer, oldImage, started)
577. 			detail := fmt.Errorf("MACHINE IN UNKNOWN STATE host=%s — manual intervention required; deploy: %v; rollback: %v", host, runErr, rerr)
578. 			if fmErr != nil {
579. 				detail = fmt.Errorf("%v; failed-manifest write error: %v", detail, fmErr)
580. 			}
581. 			return nil, coded("ERR_ROLLBACK_FAILED", host, "ROLLBACK", detail)
582. 		}
583. 		// §10.2/§10.4: the container is back on the previous image and running.
584. 		// Persist a rolled_back manifest at the previous version (image id = the
585. 		// restored image) so Read reports the restored state instead of treating the
586. 		// resource as absent — mirroring the file-based rollback (rollbackSingle) and
587. 		// the docker failed-rollback branch, both of which persist a manifest. A
588. 		// FINALIZE failure here leaves the machine restored but unrecorded, so it is
589. 		// surfaced as ERR_ROLLBACK_FAILED (UNKNOWN STATE) exactly like the file path.
590. 		// Skipped when no previous version is known (unmanaged container): there is
591. 		// no version to record.
592. 		if prev != "" {
593. 			rm := &Manifest{Schema: 1, App: s.Metadata.Name, Pattern: string(s.Pattern.Type),
594. 				CurrentVersion: prev, CurrentRelease: "docker://" + rc.Spec.Pattern.ContainerName,
595. 				ProviderVersion: ProviderVersion,
596. 				Extra:           map[string]string{"image_id": oldImage, "config_hash": dc.ConfigFingerprint(rbRC)},
597. 				LastOperation: LastOp{Type: "deploy", Result: "rolled_back",
598. 					Started: started.Format(time.RFC3339), Finished: time.Now().UTC().Format(time.RFC3339)},
599. 			}
600. 			if werr := sl.timed(ctx, "FINALIZE", func() error {
601. 				if derr := ensureDir(ctx, t, p.Root); derr != nil {
602. 					return derr
603. 				}
604. 				return WriteManifest(ctx, t, p, rm)
605. 			}); werr != nil {
606. 				return nil, coded("ERR_ROLLBACK_FAILED", host, "ROLLBACK",
607. 					fmt.Errorf("MACHINE IN UNKNOWN STATE host=%s — restored to previous image %s but manifest write failed: %v; deploy error: %v",
608. 						host, short(oldImage), werr, runErr))
609. 			}
610. 		}
611. 		return nil, fmt.Errorf("%w; rolled back to previous image %s", runErr, short(oldImage))
612. 	}
613. 	// D3-equivalent post-run inspect: the recorded image id backs a FUTURE
614. 	// rollback. The new container is ALREADY RUNNING at this point, so a missing/
615. 	// failed inspect must NOT just error out and leave Terraform pointing at the
616. 	// OLD version while the machine runs the new one (evaluator iter3 item 2).
617. 	// Persist a FAILED manifest at the NEW version so Read reports drift
618. 	// (deployed_version = "<new>!failed") and a re-apply converges the state to
619. 	// match the actually-running container.
620. 	newImage, ierr := dc.CurrentImageID(ctx, t, rc)
621. 	if ierr != nil || strings.TrimSpace(newImage) == "" {
622. 		fmErr := e.dockerFinalizeFailed(ctx, sl, t, s, p, s.Artifact.Version, strings.TrimSpace(newImage), started)
623. 		out := coded("ERR_CONNECT", host, "FINALIZE",
624. 			fmt.Errorf("container started at %s but its image id could not be recorded (inspect err=%v, image_id=%q); recorded failed state for reconvergence", s.Artifact.Version, ierr, newImage))
625. 		if fmErr != nil {
626. 			return nil, coded("ERR_CONNECT", host, "FINALIZE", fmt.Errorf("%v; failed-manifest write error: %v", out, fmErr))
627. 		}
628. 		return nil, out
629. 	}
630. 	nm := &Manifest{Schema: 1, App: s.Metadata.Name, Pattern: string(s.Pattern.Type),
631. 		CurrentVersion: s.Artifact.Version, PreviousVersion: prev,
632. 		CurrentRelease:  "docker://" + rc.Spec.Pattern.ContainerName,
633. 		ProviderVersion: ProviderVersion,
634. 		Extra:           map[string]string{"image_id": newImage, "config_hash": dc.ConfigFingerprint(rc)},
635. 		LastOperation: LastOp{Type: "deploy", Result: "success",
636. 			Started: started.Format(time.RFC3339), Finished: time.Now().UTC().Format(time.RFC3339)},
637. 	}
638. 	// A FINALIZE failure means the new container is running but its manifest was
639. 	// not persisted — the deploy is NOT durably recorded, so fail closed instead
640. 	// of reporting success (evaluator item 9).
641. 	if ferr := sl.timed(ctx, "FINALIZE", func() error {
642. 		if err := ensureDir(ctx, t, p.Root); err != nil {
643. 			return err
644. 		}
645. 		return WriteManifest(ctx, t, p, nm)
646. 	}); ferr != nil {
647. 		return nil, coded("ERR_CONNECT", host, "FINALIZE", ferr)
648. 	}
649. 	st, _ := dc.Status(ctx, t, rc)
650. 	return statusFrom(nm, host, st), nil
651. }
