 	rc := dockerRC(spec.OSLinux, dockerPattern(), spec.Source{
 		Type: "docker_registry", Image: "registry.example.com/app", Tag: "2.0.0",
 	}, nil)

 	present := &scriptTransport{osKind: spec.OSLinux, queue: []transport.Result{
