192. // Scenario: D3 image-id inspect. CurrentImageID runs `docker inspect -f
193. // '{{.Image}}'` and returns the trimmed id; an absent container yields "" with
194. // no error. This is the recorded rollback anchor (DESIGN §9.6 D3) the engine
195. // persists into manifest.extra.image_id.
196. func TestDockerCurrentImageID(t *testing.T) {
197. 	var d DockerContainer
198. 	rc := dockerRC(spec.OSLinux, dockerPattern(), spec.Source{
199. 		Type: "docker_registry", Image: "registry.example.com/app", Tag: "2.0.0",
200. 	}, nil)
201. 
202. 	present := &scriptTransport{osKind: spec.OSLinux, queue: []transport.Result{
203. 		{ExitCode: 0, Stdout: "sha256:abc123\n"},
204. 	}}
205. 	got, err := d.CurrentImageID(context.Background(), present, rc)
206. 	if err != nil {
207. 		t.Fatalf("CurrentImageID: %v", err)
208. 	}
209. 	if got != "sha256:abc123" {
