252. // ConfigFingerprint hashes the MUTABLE docker_container settings — image ref
253. // (tag or digest), container name, restart policy, ports, volumes, run_args and
254. // the rendered env — so the engine can tell a same-version CONFIGURATION change
255. // (new tag/digest, ports, env, volumes, restart, run args) apart from a true
256. // no-op and avoid silently ignoring it (DESIGN §10.1). Ports/volumes/env are
257. // order-normalized; run_args keep author order (docker flag order is meaningful).
258. func (d *DockerContainer) ConfigFingerprint(rc ReleaseCtx) string {
259. 	p := rc.Spec.Pattern
260. 	restart := p.RestartPolicy
261. 	if restart == "" {
262. 		restart = "unless-stopped"
263. 	}
264. 	h := sha256.New()
265. 	fmt.Fprintf(h, "ref=%s\n", imageRef(&rc.Spec.Artifact))
266. 	fmt.Fprintf(h, "name=%s\n", p.ContainerName)
267. 	fmt.Fprintf(h, "restart=%s\n", restart)
268. 	ports := append([]string(nil), p.Ports...)
269. 	sort.Strings(ports)
270. 	for _, x := range ports {
271. 		fmt.Fprintf(h, "port=%s\n", x)
272. 	}
273. 	vols := append([]string(nil), p.Volumes...)
274. 	sort.Strings(vols)
275. 	for _, x := range vols {
276. 		fmt.Fprintf(h, "vol=%s\n", x)
277. 	}
278. 	for _, x := range p.RunArgs {
279. 		fmt.Fprintf(h, "arg=%s\n", x)
280. 	}
281. 	keys := make([]string, 0, len(rc.Env))
282. 	for k := range rc.Env {
283. 		keys = append(keys, k)
284. 	}
285. 	sort.Strings(keys)
286. 	for _, k := range keys {
287. 		fmt.Fprintf(h, "env=%s=%s\n", k, rc.Env[k])
288. 	}
289. 	return hex.EncodeToString(h.Sum(nil))
290. }
