1. package engine
2. 
3. import (
4. 	"context"
5. 	"fmt"
6. 	"strings"
7. 	"testing"
8. 
9. 	"github.com/smartpcr/terraform-provider-labdeploy/internal/spec"
10. 	"github.com/smartpcr/terraform-provider-labdeploy/internal/transport"
11. )
12. 
13. // dockerNode embeds a fakeHost and answers the §9.6 docker D-step scripts
14. // (pull/inspect/run/stop) against a tiny in-memory container state; all other
15. // scripts (connect/preflight/lock/manifest) delegate to the embedded fake.
16. type dockerNode struct {
17. 	*fakeHost
18. 	image         string   // current container image id ("" ⇒ container absent)
19. 	runImage      string   // image id a normal (new-ref) docker run switches the container to
20. 	rollbackImage string   // image id a rollback run (ref == this) switches the container to
21. 	pullErr       bool
22. 	runErr        bool     // docker run fails for BOTH the new ref and the rollback ref
23. 	runScripts    []string // every `docker run` script, in order (new ref then rollback ref)
24. 	inspectErr    bool     // ALL `docker inspect {{.Image}}` probes fail with a transport error
25. 	inspectErrAfterRun bool // `docker inspect {{.Image}}` fails only AFTER a docker run has executed
26. 	didRun        bool     // set once any docker run script has been dispatched
27. }
28. 
29. func (n *dockerNode) Exec(ctx context.Context, c transport.Cmd) (transport.Result, error) {
30. 	s := c.Script
31. 	switch {
32. 	case strings.Contains(s, "docker pull"):
33. 		if n.pullErr {
34. 			return transport.Result{ExitCode: 40, Stderr: "pull failed"}, nil
35. 		}
36. 		return ok(""), nil
37. 	case strings.Contains(s, "docker inspect") && strings.Contains(s, "{{.Image}}"):
38. 		// Simulate a genuine transport failure of the D3 inspect. inspectErr fails
39. 		// the PRE-run probe (rollback anchor cannot be recorded); inspectErrAfterRun
40. 		// fails only the POST-run probe (new container already running).
41. 		if n.inspectErr || (n.inspectErrAfterRun && n.didRun) {
42. 			return transport.Result{}, fmt.Errorf("transport: docker inspect unreachable")
43. 		}
44. 		return ok(n.image), nil
45. 	case strings.Contains(s, "docker inspect") && strings.Contains(s, "{{.State.Running}}"):
46. 		if n.image == "" {
47. 			return ok("not_installed"), nil
48. 		}
49. 		return ok("running"), nil
50. 	case strings.Contains(s, "docker run"):
51. 		n.runScripts = append(n.runScripts, s)
52. 		n.didRun = true
53. 		if n.runErr {
54. 			return transport.Result{ExitCode: 44, Stderr: "run failed"}, nil
55. 		}
56. 		// Reflect the image the container now runs: a rollback run (ref == the
57. 		// recorded old image id) restores rollbackImage; a normal run switches to
58. 		// runImage. This lets healthGate distinguish new-vs-restored by n.image.
59. 		switch {
60. 		case n.rollbackImage != "" && strings.Contains(s, n.rollbackImage):
61. 			n.image = n.rollbackImage
62. 		case n.runImage != "":
63. 			n.image = n.runImage
64. 		}
65. 		return ok(""), nil
66. 	case strings.Contains(s, "docker stop"):
67. 		return ok(""), nil
68. 	}
69. 	return n.fakeHost.Exec(ctx, c)
70. }
71. 
72. // TestDockerRollbackFailedNoManifest covers evaluator iter6 item 2 / DESIGN
73. // §10.6: a docker update failure where an UNMANAGED old container exists
74. // (old image id present) but NO prior manifest does (prev==""), and the
75. // rollback to the old image also fails. The failed manifest must still be
76. // persisted (recorded at the ATTEMPTED version) and ERR_ROLLBACK_FAILED
77. // returned — the old bug passed empty prev to dockerFinalizeFailed which no-op'd.
78. func TestDockerRollbackFailedNoManifest(t *testing.T) {
79. 	n := &dockerNode{fakeHost: newFakeHost("lab-01"), image: "sha256:oldimg", runErr: true}
80. 	eng := New()
81. 	eng.NewTransport = func(tg *spec.Target, host string) (transport.Transport, error) { return n, nil }
82. 
83. 	_, err := eng.Deploy(context.Background(), dockerSpec(t, "2.0.0"))
84. 	var ce *CodedError
85. 	if !asCoded(err, &ce) || ce.Code != "ERR_ROLLBACK_FAILED" {
86. 		t.Fatalf("want ERR_ROLLBACK_FAILED, got %v", err)
87. 	}
88. 	if !strings.Contains(err.Error(), "MACHINE IN UNKNOWN STATE host=lab-01") {
89. 		t.Fatalf("want MACHINE IN UNKNOWN STATE host=lab-01 detail, got: %v", err)
90. 	}
91. 	m := string(n.fakeHost.files[`C:\deploy\sample-svc\manifest.json`])
92. 	if m == "" {
93. 		t.Fatalf("docker rollback failure with no prior manifest must still persist a failed manifest; none written (log=%v)", n.fakeHost.log)
94. 	}
95. 	if !strings.Contains(m, `"current_version": "2.0.0"`) || !strings.Contains(m, `"result": "failed"`) {
96. 		t.Fatalf("failed manifest must record the attempted version 2.0.0 with result=failed: %s", m)
97. 	}
98. }
99. 
100. // dockerSpec is a minimal docker_container Deployment at the given version.
101. func dockerSpec(t *testing.T, version string) *spec.Deployment {
102. 	t.Helper()
103. 	t.Setenv("LABDEPLOY_PASSWORD", "pw")
104. 	y := `
105. apiVersion: labdeploy/v1
106. kind: Deployment
107. metadata: { name: sample-svc }
108. target:
109.   transport: winrm
110.   hosts: ["lab-01"]
111.   os: windows
112.   credentials: { username: u, password_env: LABDEPLOY_PASSWORD }
113. artifact:
114.   type: docker_image
115.   version: ` + version + `
116.   source: { type: docker_registry, image: registry.example.com/app, tag: "` + version + `" }
117. pattern:
118.   type: docker_container
119.   container_name: sample
120. health_check:
121.   type: http
122.   http: { url: "http://localhost:8080/health" }
123.   initial_delay_seconds: 1
124.   interval_seconds: 1
125.   timeout_seconds: 3
126. strategy: { keep_releases: 2, rollback_on_failure: true }
127. `
128. 	d, _, err := spec.ParseDeployment(y, nil, "")
129. 	if err != nil {
130. 		t.Fatalf("spec: %v", err)
131. 	}
132. 	return d
133. }
134. 
135. const dockerManifestPath = `C:\deploy\sample-svc\manifest.json`
136. 
137. // TestDockerDeploySuccessRecordsImageID covers evaluator iter2 item 1 (positive
138. // half): a successful docker deploy must persist the post-run image id into
139. // manifest.extra.image_id (DESIGN §9.6 D3 record) so a later rollback has an
140. // anchor. The post-run inspect returns the NEW image id, which must land in the
141. // success manifest.
142. func TestDockerDeploySuccessRecordsImageID(t *testing.T) {
143. 	n := &dockerNode{fakeHost: newFakeHost("lab-01"), image: "", runImage: "sha256:newimg"}
144. 	eng := New()
145. 	eng.NewTransport = func(tg *spec.Target, host string) (transport.Transport, error) { return n, nil }
146. 
147. 	if _, err := eng.Deploy(context.Background(), dockerSpec(t, "2.0.0")); err != nil {
148. 		t.Fatalf("docker deploy should succeed: %v", err)
149. 	}
150. 	m := string(n.fakeHost.files[dockerManifestPath])
151. 	if m == "" {
152. 		t.Fatalf("successful docker deploy must persist a manifest; none written (log=%v)", n.fakeHost.log)
153. 	}
154. 	if !strings.Contains(m, `"current_version": "2.0.0"`) || !strings.Contains(m, `"result": "success"`) {
155. 		t.Fatalf("success manifest must record version 2.0.0 result=success: %s", m)
156. 	}
157. 	if !strings.Contains(m, `"image_id": "sha256:newimg"`) {
158. 		t.Fatalf("success manifest must record the post-run image id in extra.image_id: %s", m)
159. 	}
160. }
161. 
162. // TestDockerDeployEmptyImageIDFailsClosed covers evaluator iter2 item 1 (the
163. // durability half): if the post-run inspect yields an EMPTY image id the deploy
164. // is not durably recorded (no rollback anchor), so the engine must fail closed —
165. // NOT report success and persist a manifest with an empty image_id.
166. func TestDockerDeployEmptyImageIDFailsClosed(t *testing.T) {
167. 	n := &dockerNode{fakeHost: newFakeHost("lab-01"), image: "", runImage: ""} // run ok, inspect stays ""
168. 	eng := New()
