13. // dockerNode embeds a fakeHost and answers the §9.6 docker D-step scripts
14. // (pull/inspect/run/stop) against a tiny in-memory container state; all other
15. // scripts (connect/preflight/lock/manifest) delegate to the embedded fake.
16. type dockerNode struct {
17. 	*fakeHost
18. 	image         string   // current container image id ("" ⇒ container absent)
19. 	runImage      string   // image id a normal (new-ref) docker run switches the container to
20. 	rollbackImage string   // image id a rollback run (ref == this) switches the container to
21. 	pullErr       bool
22. 	runErr        bool     // docker run fails for BOTH the new ref and the rollback ref
23. 	runScripts    []string // every `docker run` script, in order (new ref then rollback ref)
24. 	inspectErr    bool     // ALL `docker inspect {{.Image}}` probes fail with a transport error
25. 	inspectErrAfterRun bool // `docker inspect {{.Image}}` fails only AFTER a docker run has executed
26. 	didRun        bool     // set once any docker run script has been dispatched
27. }
