29. func (n *dockerNode) Exec(ctx context.Context, c transport.Cmd) (transport.Result, error) {
30. 	s := c.Script
31. 	switch {
32. 	case strings.Contains(s, "docker pull"):
33. 		if n.pullErr {
34. 			return transport.Result{ExitCode: 40, Stderr: "pull failed"}, nil
35. 		}
36. 		return ok(""), nil
37. 	case strings.Contains(s, "docker inspect") && strings.Contains(s, "{{.Image}}"):
38. 		// Simulate a genuine transport failure of the D3 inspect. inspectErr fails
39. 		// the PRE-run probe (rollback anchor cannot be recorded); inspectErrAfterRun
40. 		// fails only the POST-run probe (new container already running).
41. 		if n.inspectErr || (n.inspectErrAfterRun && n.didRun) {
42. 			return transport.Result{}, fmt.Errorf("transport: docker inspect unreachable")
43. 		}
44. 		return ok(n.image), nil
45. 	case strings.Contains(s, "docker inspect") && strings.Contains(s, "{{.State.Running}}"):
46. 		if n.image == "" {
47. 			return ok("not_installed"), nil
48. 		}
49. 		return ok("running"), nil
50. 	case strings.Contains(s, "docker run"):
51. 		n.runScripts = append(n.runScripts, s)
52. 		n.didRun = true
53. 		if n.runErr {
54. 			return transport.Result{ExitCode: 44, Stderr: "run failed"}, nil
55. 		}
56. 		// Reflect the image the container now runs: a rollback run (ref == the
57. 		// recorded old image id) restores rollbackImage; a normal run switches to
58. 		// runImage. This lets healthGate distinguish new-vs-restored by n.image.
59. 		switch {
60. 		case n.rollbackImage != "" && strings.Contains(s, n.rollbackImage):
61. 			n.image = n.rollbackImage
62. 		case n.runImage != "":
63. 			n.image = n.runImage
64. 		}
65. 		return ok(""), nil
66. 	case strings.Contains(s, "docker stop"):
67. 		return ok(""), nil
68. 	}
