 // dockerSpec is a minimal docker_container Deployment at the given version.
 func dockerSpec(t *testing.T, version string) *spec.Deployment {
 	t.Helper()
 	t.Setenv("LABDEPLOY_PASSWORD", "pw")
 	y := `
