 			logout = fmt.Sprintf("docker logout%s | Out-Null", regArg)
 		} else {
 			login = fmt.Sprintf(`printf '%%s' "$LD_REG_PW" | docker login%s -u %s --password-stdin || { echo 'docker login failed' >&2; exit 40; }`, regArg, user)
