 	var script string
 	if t.OS() == spec.OSWindows {
 		script = fmt.Sprintf(`%s
 docker pull %s
 $code=$LASTEXITCODE
 %s
 if($code -ne 0){ exit 40 }
 exit 0`, login, qref, logout)
 	} else {
 		script = fmt.Sprintf(`%s
 docker pull %s; code=$?
 %s
 [ $code -eq 0 ] || exit 40
 exit 0`, login, qref, logout)
 	}
