223. // Scenario: unsafe environment/argument rendering (evaluator iter2 item 3). A
224. // container env value carrying shell metacharacters ($(), backtick, $VAR, a
225. // single quote) must be rendered as a single-quoted literal so neither sh nor
226. // PowerShell can interpret it — no command substitution, no variable expansion.
227. func TestDockerRunArgMetacharSafe(t *testing.T) {
228. 	inj := "$(touch pwned)`id`$HOME he'llo"
229. 	pat := dockerPattern()
230. 	src := spec.Source{Type: "docker_registry", Image: "registry.example.com/app", Tag: "2.0.0"}
231. 
232. 	// Linux: single-quote with '\'' escaping for the embedded apostrophe.
233. 	rcL := dockerRC(spec.OSLinux, pat, src, map[string]string{"INJ": inj})
234. 	fL := &scriptTransport{osKind: spec.OSLinux}
235. 	if err := (&DockerContainer{}).Start(context.Background(), fL, rcL); err != nil {
236. 		t.Fatalf("Start(linux): %v", err)
237. 	}
238. 	wantL := `-e 'INJ=$(touch pwned)` + "`id`" + `$HOME he'\''llo'`
239. 	if !strings.Contains(fL.scripts[0], wantL) {
240. 		t.Errorf("linux env value must be single-quoted literal (no command substitution):\nwant substring %q\n got %s", wantL, fL.scripts[0])
241. 	}
242. 	// The metacharacters must never appear OUTSIDE a single-quoted context.
243. 	if strings.Contains(fL.scripts[0], `-e "INJ=`) || strings.Contains(fL.scripts[0], "-e INJ=$(") {
244. 		t.Errorf("linux env must not be double-quoted or bare (injection risk):\n%s", fL.scripts[0])
245. 	}
246. 
247. 	// Windows/PowerShell: single-quote with '' escaping for the apostrophe.
248. 	rcW := dockerRC(spec.OSWindows, pat, src, map[string]string{"INJ": inj})
249. 	fW := &scriptTransport{osKind: spec.OSWindows}
250. 	if err := (&DockerContainer{}).Start(context.Background(), fW, rcW); err != nil {
251. 		t.Fatalf("Start(windows): %v", err)
252. 	}
253. 	wantW := `-e 'INJ=$(touch pwned)` + "`id`" + `$HOME he''llo'`
254. 	if !strings.Contains(fW.scripts[0], wantW) {
255. 		t.Errorf("windows env value must be single-quoted literal (PowerShell no-expansion):\nwant substring %q\n got %s", wantW, fW.scripts[0])
256. 	}
257. 	// PowerShell backslash-quote escaping (the old, broken form) must be gone.
258. 	if strings.Contains(fW.scripts[0], `\"`) {
259. 		t.Errorf("windows env must not use invalid backslash-quote escaping:\n%s", fW.scripts[0])
260. 	}
261. }
