298. // Scenario: complete container-name quoting (evaluator iter3 item 4). The
299. // container name flows into D2 rm -f, D3 inspect (CurrentImageID), Status,
300. // Stop and Uninstall. A name carrying shell metacharacters must be rendered as
301. // a single-quoted literal on EVERY path so neither sh nor PowerShell can
302. // interpret it; the raw metacharacter sequence must never appear unquoted.
303. func TestDockerContainerNameMetacharSafe(t *testing.T) {
304. 	inj := "svc; rm -rf / #$(id)"
305. 	src := spec.Source{Type: "docker_registry", Image: "registry.example.com/app", Tag: "2.0.0"}
306. 
307. 	for _, os := range []spec.OSKind{spec.OSLinux, spec.OSWindows} {
308. 		pat := dockerPattern()
309. 		pat.ContainerName = inj
310. 		rc := dockerRC(os, pat, src, nil)
311. 		wantLit := "'" + inj + "'" // sh and PS both single-quote; no apostrophe in inj
312. 
313. 		type probe struct {
314. 			name string
315. 			run  func(tr *scriptTransport) error
316. 		}
317. 		d := &DockerContainer{}
318. 		probes := []probe{
319. 			{"Start(rm -f + run)", func(tr *scriptTransport) error { return d.Start(context.Background(), tr, rc) }},
320. 			{"CurrentImageID(inspect)", func(tr *scriptTransport) error {
321. 				tr.queue = []transport.Result{{ExitCode: 0, Stdout: ""}}
322. 				_, err := d.CurrentImageID(context.Background(), tr, rc)
323. 				return err
324. 			}},
325. 			{"Status(inspect)", func(tr *scriptTransport) error {
326. 				tr.queue = []transport.Result{{ExitCode: 0, Stdout: "running"}}
327. 				_, err := d.Status(context.Background(), tr, rc)
328. 				return err
329. 			}},
330. 			{"Stop", func(tr *scriptTransport) error { return d.Stop(context.Background(), tr, rc) }},
331. 			{"Uninstall", func(tr *scriptTransport) error { return d.Uninstall(context.Background(), tr, rc, false) }},
332. 		}
333. 		for _, pr := range probes {
334. 			tr := &scriptTransport{osKind: os}
335. 			if err := pr.run(tr); err != nil {
336. 				t.Fatalf("%s/%s: %v", os, pr.name, err)
337. 			}
338. 			joined := strings.Join(tr.scripts, "\n")
339. 			if !strings.Contains(joined, wantLit) {
340. 				t.Errorf("%s/%s: container name must be single-quoted literal %q:\n%s", os, pr.name, wantLit, joined)
341. 			}
342. 			// The bare, unquoted injection must never appear (would allow `rm -rf /`).
343. 			bare := "-f " + inj
344. 			if strings.Contains(joined, bare) {
345. 				t.Errorf("%s/%s: container name rendered unquoted (injection):\n%s", os, pr.name, joined)
346. 			}
347. 		}
348. 	}
349. }
