351. // Scenario: same-version configuration fingerprint (evaluator iter3 item 3). The
352. // engine keys idempotency off ConfigFingerprint so a same-version change to the
353. // mutable container settings is NOT a silent no-op. The fingerprint must change
354. // when image ref, ports, env, volumes, restart policy or run_args change, and be
355. // stable (order-insensitive for ports/volumes/env) otherwise.
356. func TestDockerConfigFingerprint(t *testing.T) {
357. 	d := &DockerContainer{}
358. 	src := spec.Source{Type: "docker_registry", Image: "registry.example.com/app", Tag: "2.0.0"}
359. 	base := dockerRC(spec.OSLinux, dockerPattern(), src, map[string]string{"A": "1", "B": "2"})
360. 	baseFP := d.ConfigFingerprint(base)
361. 
362. 	// Identical config ⇒ identical fingerprint (no-op).
363. 	if got := d.ConfigFingerprint(dockerRC(spec.OSLinux, dockerPattern(), src, map[string]string{"A": "1", "B": "2"})); got != baseFP {
364. 		t.Errorf("identical config must produce identical fingerprint:\n base=%s\n got =%s", baseFP, got)
365. 	}
366. 
367. 	// Each mutable dimension must move the fingerprint.
368. 	mut := map[string]ReleaseCtx{
369. 		"image tag": dockerRC(spec.OSLinux, dockerPattern(),
370. 			spec.Source{Type: "docker_registry", Image: "registry.example.com/app", Tag: "2.0.1"},
371. 			map[string]string{"A": "1", "B": "2"}),
372. 	}
373. 	patDigest := dockerPattern()
374. 	mut["digest"] = dockerRC(spec.OSLinux, patDigest,
375. 		spec.Source{Type: "docker_registry", Image: "registry.example.com/app", Digest: "sha256:deadbeef"},
376. 		map[string]string{"A": "1", "B": "2"})
377. 	patPorts := dockerPattern()
378. 	patPorts.Ports = []string{"1234:1234"}
379. 	mut["ports"] = dockerRC(spec.OSLinux, patPorts, src, map[string]string{"A": "1", "B": "2"})
380. 	patVols := dockerPattern()
381. 	patVols.Volumes = []string{"/x:/y"}
382. 	mut["volumes"] = dockerRC(spec.OSLinux, patVols, src, map[string]string{"A": "1", "B": "2"})
383. 	patRestart := dockerPattern()
384. 	patRestart.RestartPolicy = "no"
385. 	mut["restart"] = dockerRC(spec.OSLinux, patRestart, src, map[string]string{"A": "1", "B": "2"})
386. 	patArgs := dockerPattern()
387. 	patArgs.RunArgs = []string{"--pull=always"}
388. 	mut["run_args"] = dockerRC(spec.OSLinux, patArgs, src, map[string]string{"A": "1", "B": "2"})
389. 	mut["env"] = dockerRC(spec.OSLinux, dockerPattern(), src, map[string]string{"A": "9", "B": "2"})
390. 	for name, rc := range mut {
391. 		if got := d.ConfigFingerprint(rc); got == baseFP {
392. 			t.Errorf("changing %s must change the fingerprint, but it stayed %s", name, baseFP)
393. 		}
394. 	}
395. 
396. 	// Order-insensitive for ports/volumes/env (map + sorted slices).
397. 	patReorder := dockerPattern()
398. 	patReorder.Ports = []string{"9090:9090", "8080:8080"}
399. 	reorder := dockerRC(spec.OSLinux, patReorder, src, map[string]string{"B": "2", "A": "1"})
400. 	if got := d.ConfigFingerprint(reorder); got != baseFP {
401. 		t.Errorf("reordered ports/env must NOT change the fingerprint:\n base=%s\n got =%s", baseFP, got)
402. 	}
403. }
