653. // dockerFinalizeFailed persists a failed manifest for the docker path (DESIGN
654. // §10.2/§10.6) recording last_operation.result=failed. The manifest write is
655. // emitted as a structured FINALIZE step (evaluator iter5 item 3).
656. func (e *Engine) dockerFinalizeFailed(ctx context.Context, sl stepLogger, t transport.Transport, s *spec.Deployment,
657. 	p layout.Paths, prev, prevImage string, started time.Time) error {
658. 	if prev == "" {
659. 		return nil
660. 	}
661. 	m := &Manifest{Schema: 1, App: s.Metadata.Name, Pattern: string(s.Pattern.Type),
662. 		CurrentVersion: prev, CurrentRelease: "docker://" + s.Pattern.ContainerName,
663. 		ProviderVersion: ProviderVersion,
