263. // Scenario: Docker preflight fail (DESIGN §8.1 / §9.6 D14). Given `docker version`
264. // failing via a fake transport with a scripted Result queue, Preflight must yield
265. // a StepError coded ERR_PREFLIGHT at step=PREFLIGHT.
266. func TestDockerPreflightFail(t *testing.T) {
267. 	var d DockerContainer
268. 	rc := dockerRC(spec.OSLinux, dockerPattern(), spec.Source{
269. 		Type: "docker_registry", Image: "registry.example.com/app", Tag: "2.0.0",
270. 	}, nil)
271. 
272. 	// docker daemon unavailable: non-zero exit from `docker version`.
273. 	fail := &scriptTransport{osKind: spec.OSLinux, queue: []transport.Result{
274. 		{ExitCode: 1, Stderr: "Cannot connect to the Docker daemon"},
275. 	}}
276. 	err := d.Preflight(context.Background(), fail, rc)
277. 	if err == nil {
278. 		t.Fatal("Preflight must fail when `docker version` exits non-zero")
279. 	}
280. 	var se *StepError
281. 	if !errors.As(err, &se) {
282. 		t.Fatalf("expected *StepError, got %T: %v", err, err)
283. 	}
284. 	if se.Code != "ERR_PREFLIGHT" || se.Step != "PREFLIGHT" {
285. 		t.Errorf("preflight failure must be step=PREFLIGHT code=ERR_PREFLIGHT, got step=%q code=%q", se.Step, se.Code)
286. 	}
287. 	if len(fail.scripts) != 1 || !strings.Contains(fail.scripts[0], "docker version") {
288. 		t.Errorf("Preflight must probe `docker version`, scripts=%v", fail.scripts)
289. 	}
290. 
291. 	// Healthy daemon: exit 0 ⇒ no error.
292. 	okT := &scriptTransport{osKind: spec.OSLinux, queue: []transport.Result{{ExitCode: 0, Stdout: "24.0.7"}}}
293. 	if err := d.Preflight(context.Background(), okT, rc); err != nil {
294. 		t.Fatalf("Preflight must succeed when `docker version` exits 0: %v", err)
295. 	}
296. }
