 		d := &DockerContainer{}
 		probes := []probe{
 			{"Start(rm -f + run)", func(tr *scriptTransport) error { return d.Start(context.Background(), tr, rc) }},
 			{"CurrentImageID(inspect)", func(tr *scriptTransport) error {
