484. // deployDocker = D-steps (DESIGN §9.6) with image-id rollback. Emits the same
485. // structured step records as the file-based path for its executed steps: FETCH
486. // (image pull), START (rm -f old + run new), HEALTH, FINALIZE (manifest write),
487. // and ROLLBACK on failure — each carrying app/host/step/version/duration_ms.
488. func (e *Engine) deployDocker(ctx context.Context, sl stepLogger, t transport.Transport, s *spec.Deployment,
489. 	p layout.Paths, dc *pattern.DockerContainer, rc pattern.ReleaseCtx, m *Manifest) (*Status, error) {
490. 	host := t.Host()
491. 	sl = sl.forHost(host)
492. 	started := time.Now().UTC()
493. 	if m != nil && m.CurrentVersion == s.Artifact.Version && m.Extra["config_hash"] == dc.ConfigFingerprint(rc) {
494. 		// True no-op only when the version AND the mutable container configuration
495. 		// (image ref/ports/env/volumes/restart/run_args) are unchanged AND running
496. 		// (DESIGN §10.1). A same-version config change has a different fingerprint
497. 		// and falls through to a redeploy instead of being silently ignored.
498. 		if st, err := dc.Status(ctx, t, rc); err == nil && st == "running" {
499. 			return statusFrom(m, host, st), nil
500. 		}
501. 	}
502. 	prev, oldImage := "", ""
503. 	if m != nil {
504. 		prev = m.CurrentVersion
505. 		oldImage = m.Extra["image_id"]
506. 	}
507. 	// Best-effort log/event collection on every exit path from here (including
508. 	// image-pull failure) — DESIGN §6.5. No-op when nothing is configured.
509. 	defer e.collectDeploymentLogs(ctx, t, s, p, started)
510. 	fetchStart := time.Now()
511. 	perr := dc.Pull(ctx, t, rc)
512. 	sl.emit(ctx, "FETCH", fetchStart)
513. 	if perr != nil {
514. 		return nil, perr
515. 	}
516. 	// D3 (pre-run inspect): record the live image id as the rollback anchor. A
517. 	// TRANSPORT error here must abort BEFORE D4 `rm -f` — destroying the running
518. 	// container with no recorded rollback image would leave the target
519. 	// unrecoverable (evaluator iter3 item 1). An absent container is reported as
520. 	// ("", nil) by CurrentImageID, so only a real failure surfaces an error.
521. 	cur, cerr := dc.CurrentImageID(ctx, t, rc)
522. 	if cerr != nil {
523. 		return nil, cerr
524. 	}
525. 	if cur != "" {
526. 		oldImage = cur
527. 	}
528. 	runErr := sl.timed(ctx, "START", func() error { return dc.Start(ctx, t, rc) }) // rm -f old + run new
529. 	if runErr == nil {
530. 		runErr = sl.timed(ctx, "HEALTH", func() error {
531. 			return RunHealthCheck(ctx, t, &s.HealthCheck, p.Root, rc.Env)
532. 		})
533. 	}
534. 	if runErr != nil {
535. 		if !s.Strategy.EffectiveRollback() || oldImage == "" {
536. 			// §10.2: record last_operation=failed so Read reports drift even when no
537. 			// rollback is performed (rollback disabled or previous image unknown).
538. 			// Record at the previous version if known, else the attempted version so
539. 			// a fresh docker failure still persists failed state (evaluator iter5 item 2).
