1. package engine
2. 
3. import (
4. 	"context"
5. 	"fmt"
6. 	"strings"
7. 	"testing"
8. 
9. 	"github.com/smartpcr/terraform-provider-labdeploy/internal/spec"
10. 	"github.com/smartpcr/terraform-provider-labdeploy/internal/transport"
11. )
12. 
13. // dockerNode embeds a fakeHost and answers the §9.6 docker D-step scripts
14. // (pull/inspect/run/stop) against a tiny in-memory container state; all other
15. // scripts (connect/preflight/lock/manifest) delegate to the embedded fake.
16. type dockerNode struct {
17. 	*fakeHost
18. 	image         string   // current container image id ("" ⇒ container absent)
19. 	runImage      string   // image id a normal (new-ref) docker run switches the container to
20. 	rollbackImage string   // image id a rollback run (ref == this) switches the container to
21. 	pullErr       bool
22. 	runErr        bool     // docker run fails for BOTH the new ref and the rollback ref
23. 	runScripts    []string // every `docker run` script, in order (new ref then rollback ref)
24. 	inspectErr    bool     // ALL `docker inspect {{.Image}}` probes fail with a transport error
25. 	inspectErrAfterRun bool // `docker inspect {{.Image}}` fails only AFTER a docker run has executed
26. 	didRun        bool     // set once any docker run script has been dispatched
27. }
28. 
29. func (n *dockerNode) Exec(ctx context.Context, c transport.Cmd) (transport.Result, error) {
30. 	s := c.Script
31. 	switch {
32. 	case strings.Contains(s, "docker pull"):
33. 		if n.pullErr {
34. 			return transport.Result{ExitCode: 40, Stderr: "pull failed"}, nil
35. 		}
36. 		return ok(""), nil
37. 	case strings.Contains(s, "docker inspect") && strings.Contains(s, "{{.Image}}"):
38. 		// Simulate a genuine transport failure of the D3 inspect. inspectErr fails
39. 		// the PRE-run probe (rollback anchor cannot be recorded); inspectErrAfterRun
40. 		// fails only the POST-run probe (new container already running).
41. 		if n.inspectErr || (n.inspectErrAfterRun && n.didRun) {
42. 			return transport.Result{}, fmt.Errorf("transport: docker inspect unreachable")
43. 		}
44. 		return ok(n.image), nil
45. 	case strings.Contains(s, "docker inspect") && strings.Contains(s, "{{.State.Running}}"):
46. 		if n.image == "" {
47. 			return ok("not_installed"), nil
48. 		}
49. 		return ok("running"), nil
50. 	case strings.Contains(s, "docker run"):
51. 		n.runScripts = append(n.runScripts, s)
52. 		n.didRun = true
53. 		if n.runErr {
54. 			return transport.Result{ExitCode: 44, Stderr: "run failed"}, nil
55. 		}
56. 		// Reflect the image the container now runs: a rollback run (ref == the
57. 		// recorded old image id) restores rollbackImage; a normal run switches to
58. 		// runImage. This lets healthGate distinguish new-vs-restored by n.image.
